// Anatomy (BPT Year I): thorax and abdomen, head and neck, pelvis. Written in Learn Anywhere's own words.
window.LIB_EXTRA = (window.LIB_EXTRA || []).concat([
{
  id:"ah-vertebral-column", title:"Vertebral column: typical and atypical vertebrae, curvatures", subject:"Anatomy", region:"Spine",
  stages:"steps",
  aliases:["vertebral column","typical vertebra","atypical vertebrae","spinal curvatures","primary and secondary curves","backbone"],
  simple:"The vertebral column is a chain of 33 vertebrae that holds up the trunk and head, protects the spinal cord and lets the trunk bend and twist. Each region has vertebrae with their own special features. Seen from the side it has four curves that act like a spring to absorb load.",
  flow:["33 vertebrae: 7 cervical, 12 thoracic, 5 lumbar, sacrum, coccyx","Typical vertebra: body in front, neural arch behind","Regional features identify cervical, thoracic and lumbar vertebrae","Atypical vertebrae: C1, C2, C7, T1, T9-T12, L5","Primary curves at birth; secondary curves with head control and walking","Abnormal curves and defects guide posture assessment and exercise"],
  exam:[
    {h:"Introduction", p:["The column has 33 vertebrae: 7 cervical, 12 thoracic, 5 lumbar, 5 fused sacral and about 4 coccygeal.","Functions: supports body weight, protects spinal cord and roots, gives attachment to muscles, allows movement and forms part of the thoracic and pelvic walls."]},
    {h:"Typical vertebra", p:["Body anteriorly for weight bearing; vertebral (neural) arch posteriorly made of two pedicles and two laminae.","Seven processes: one spinous, two transverse, two superior and two inferior articular processes.","Vertebral foramen encloses the cord; notches on pedicles of adjacent vertebrae form the intervertebral foramen for the spinal nerve."]},
    {h:"Regional identification", p:["Cervical: small oval body, foramen transversarium in each transverse process, bifid spine, uncinate processes, large triangular vertebral foramen.","Thoracic: heart-shaped body with costal demifacets, costal facets on transverse processes, long spine sloping downwards, small circular foramen.","Lumbar: large kidney-shaped body, no foramen transversarium or costal facets, thick quadrangular spine, mammillary and accessory processes, triangular foramen."]},
    {h:"Atypical vertebrae", p:["C1 atlas: no body or spine; C2 axis: dens projects upward; C7 vertebra prominens: long non-bifid spine, small foramen transversarium that does not carry the vertebral artery.","T1: full facet for rib 1 and demifacet for rib 2; T9 has only upper demifacets; T10, T11, T12 have single full facets, and T11, T12 lack facets on transverse processes.","L5: largest body, wedge-shaped (deeper in front), thick transverse processes arising from pedicles and body for the iliolumbar ligament."]},
    {h:"Curvatures", p:["Primary curves (concave forward): thoracic and sacral, present in the fetus, due to the shape of the vertebral bodies.","Secondary curves (convex forward): cervical appears at about 3-4 months with head holding, lumbar at about 12-18 months with standing and walking; they depend mainly on disc shape.","Curves increase resistance to axial load, absorb shock and keep the centre of gravity over the base."]},
    {h:"Applied anatomy and physiotherapy relevance", p:["Abnormal curves: kyphosis (Scheuermann, osteoporosis), hyperlordosis (pregnancy, weak abdominals, tight hip flexors), scoliosis (lateral curve with rotation).","Spondylolysis and spondylolisthesis (usually L5 on S1); sacralisation of L5 and lumbarisation of S1; spina bifida from failure of arch fusion.","Osteoporotic wedge fractures of thoracolumbar bodies; physiotherapy uses posture training, extensor strengthening and weight-bearing exercise.","Spinous processes are palpation landmarks: C7 prominens, T3 at scapular spine, T7 at inferior angle, L4 at iliac crest level."]},
    {h:"Conclusion", p:["Knowing typical and regional features lets the student identify any vertebra, and knowing the curves underpins posture assessment."]}
  ],
  tip:"Draw a typical thoracic vertebra from above (body, pedicles, laminae, processes, foramen) and a lateral view of the column showing the four curves labelled primary and secondary.",
  evidence:[["Exercise for osteoporotic vertebral fracture","May improve pain and function; evidence is low certainty","Low"],["Scoliosis-specific exercise for adolescent idiopathic scoliosis","Possible small benefit on curve progression","Low"],["Bracing in adolescent idiopathic scoliosis","Reduces progression to surgical threshold (BrAIST trial)","Moderate-high"]],
  evidenceSource:"B D Chaurasia; Weinstein et al. NEJM 2013 (BrAIST); Cochrane reviews on exercise after vertebral fracture",
  outcomes:[["Cobb angle on X-ray","Size of scoliotic curve"],["Flexicurve or inclinometer","Thoracic kyphosis and lumbar lordosis"],["Adam forward bend test","Rib hump of structural scoliosis"]],
  recent:["The BrAIST trial (Weinstein et al., NEJM 2013) showed bracing reduced curve progression in adolescent idiopathic scoliosis."],
  mnemonic:{word:"Breakfast 7, Lunch 12, Dinner 5", items:[["7","Cervical vertebrae"],["12","Thoracic vertebrae"],["5","Lumbar vertebrae"]], extra:"Then 5 fused sacral and about 4 coccygeal."},
  example:"A 16-year-old girl from Madurai is noticed by her tailor to have one shoulder higher. On forward bending a right thoracic rib hump appears, suggesting structural scoliosis.",
  flags:["Night pain, weight loss or fever with back pain (infection such as TB spine, or tumour)","Progressive neurological deficit or bladder change","Sudden kyphotic deformity in an elderly woman after minor trauma (osteoporotic fracture)"],
  viva:[["Name the atypical thoracic vertebrae.","T1, T9, T10, T11 and T12."],["Which curves are primary?","Thoracic and sacral, concave anteriorly, present before birth."],["What passes through foramen transversarium?","Vertebral artery (C1-C6), vertebral veins and sympathetic plexus."]],
  refs:[{c:"Chaurasia BD. Human Anatomy, Volume 3: Head and Neck. Chapter: Vertebral column."},{b:"levangie",ch:"The vertebral column"},{b:"neumann",ch:"Axial skeleton: osteology and arthrology"}],
  keywords:"vertebral column typical atypical vertebrae curvatures anatomy",
  mcq:[["Which vertebra has a foramen transversarium that usually does NOT transmit the vertebral artery?",["C1","C3","C6","C7"],3,"The vertebral artery enters at C6; the C7 foramen usually carries only accessory veins."],["The secondary lumbar curve appears with:",["Head holding","Standing and walking","Birth","Puberty"],1,"Lumbar lordosis develops at about 12-18 months as the child stands and walks."]]
},
{
  id:"ah-intervertebral-joints", title:"Intervertebral joints and contents of the vertebral canal", subject:"Anatomy", region:"Spine",
  stages:"steps",
  aliases:["intervertebral disc","facet joint","zygapophyseal joint","ligamentum flavum","vertebral canal contents","cauda equina"],
  simple:"Each pair of vertebrae is joined in front by a disc and behind by two small facet joints, held together by strong ligaments. The canal formed by the stacked vertebrae holds the spinal cord, its coverings, fat, veins and nerve roots. A disc that bulges backwards can press on these roots.",
  flow:["Bodies joined by intervertebral discs (secondary cartilaginous joints)","Articular processes joined by synovial facet joints","Ligaments: ALL, PLL, flavum, interspinous, supraspinous","Canal holds cord, meninges, CSF, epidural fat and veins","Cord ends at L1-L2; cauda equina below","Disc prolapse, stenosis and cauda equina are key applied points"],
  exam:[
    {h:"Joints between vertebral bodies", p:["Secondary cartilaginous joints (symphyses) with an intervertebral disc between hyaline cartilage end plates.","Annulus fibrosus: concentric lamellae of fibrocartilage with fibres crossing obliquely; nucleus pulposus: central gel rich in proteoglycan and water, a remnant of the notochord.","There is no disc between C1 and C2 or between occiput and C1; discs make up about a quarter of the length of the presacral column and are thickest in the lumbar region."]},
    {h:"Joints between vertebral arches", p:["Zygapophyseal (facet) joints are synovial plane joints between inferior and superior articular processes.","Facet orientation decides movement: cervical oblique (all movements), thoracic near coronal (rotation and side flexion), lumbar near sagittal (flexion-extension, limited rotation).","Nerve supply: medial branches of dorsal rami, each joint receiving two levels."]},
    {h:"Ligaments", p:["Anterior longitudinal ligament: broad, front of bodies, limits extension.","Posterior longitudinal ligament: inside canal on back of bodies, narrow in the lumbar region, so discs usually herniate posterolaterally.","Ligamentum flavum: elastic, joins laminae, helps restore upright posture; interspinous, supraspinous (ligamentum nuchae in neck) and intertransverse ligaments limit flexion."]},
    {h:"Contents of the vertebral canal", p:["Spinal cord ending at the lower border of L1 (L1-L2 disc) in adults and about L3 at birth; below it the cauda equina and filum terminale.","Meninges: dura mater (dural sac ends at S2), arachnoid, pia with denticulate ligaments and filum terminale.","Spaces: epidural (fat, internal vertebral venous plexus, root sleeves), subdural (potential), subarachnoid (CSF; lumbar cistern from L2 to S2)."]},
    {h:"Nerve supply and blood supply", p:["Outer annulus and PLL by the sinuvertebral (recurrent meningeal) nerve, so the disc itself can be a pain source.","Cord supplied by one anterior and two posterior spinal arteries reinforced by segmental medullary arteries (great anterior medullary artery of Adamkiewicz in the lower thoracic region)."]},
    {h:"Applied anatomy and physiotherapy relevance", p:["Posterolateral disc prolapse at L4-L5 usually compresses the traversing L5 root; L5-S1 compresses S1.","Lumbar canal stenosis from disc bulge, facet hypertrophy and thick ligamentum flavum causes neurogenic claudication eased by flexion.","Cauda equina syndrome (saddle anaesthesia, bladder and bowel change) is an emergency; lumbar puncture is done at L3-L4 or L4-L5 below the cord.","Physiotherapy: directional preference exercise, neural mobility, core and graded activity, ergonomics; the valveless vertebral venous plexus explains spread of pelvic cancers to spine."]},
    {h:"Conclusion", p:["The three-joint complex (disc plus two facets) and canal contents explain most mechanical and neurological spinal problems seen in physiotherapy."]}
  ],
  tip:"Draw a transverse section of a lumbar motion segment showing disc (annulus, nucleus), facets, ligamentum flavum, PLL and a posterolateral herniation touching the root.",
  evidence:[["Exercise therapy for chronic low back pain","Small to moderate improvement in pain and function","Moderate"],["Surgery vs conservative care for sciatica from disc herniation","Faster early relief with surgery; similar results at 1-2 years","Moderate"],["McKenzie directional preference exercise","May help a subgroup with centralisation","Low-moderate"]],
  evidenceSource:"Cochrane review of exercise for chronic low back pain (Hayden et al. 2021); Peul et al. NEJM 2007",
  outcomes:[["Straight leg raise","Neural tension of L5-S1 roots"],["Oswestry Disability Index","Back-related disability"],["Neurological exam (myotomes, dermatomes, reflexes)","Level of root compression"]],
  recent:["Imaging studies show disc bulges and degeneration are common in people without pain, so findings must match the clinical picture."],
  mnemonic:{word:"A-P-F-I-S", items:[["A","Anterior longitudinal ligament"],["P","Posterior longitudinal ligament"],["F","Ligamentum flavum"],["I","Interspinous ligament"],["S","Supraspinous ligament"]], extra:"Front to back order of spinal ligaments."},
  example:"A 32-year-old IT worker in Bengaluru lifts a heavy water can and develops back pain with pain down the back of the leg to the lateral foot and a weak ankle reflex, pointing to S1 root compression at L5-S1.",
  flags:["Saddle anaesthesia, urinary retention or incontinence (cauda equina syndrome)","Progressive foot drop or bilateral leg weakness","Fever with back pain after spinal procedure (epidural abscess)"],
  viva:[["Why do discs herniate posterolaterally?","The PLL is narrow and weak laterally in the lumbar region."],["Where does the spinal cord end in adults?","Lower border of L1 or L1-L2 disc."],["What is the nerve supply of the disc?","Outer annulus by the sinuvertebral nerve."]],
  refs:[{c:"Chaurasia BD. Human Anatomy, Volume 3: Head and Neck. Chapter: Joints of the vertebral column."},{b:"levangie",ch:"The vertebral column"},{b:"magee",ch:"Lumbar spine"}],
  keywords:"intervertebral disc facet joint ligaments vertebral canal contents",
  mcq:[["The intervertebral disc joint is a:",["Primary cartilaginous joint","Secondary cartilaginous joint","Synovial plane joint","Fibrous syndesmosis"],1,"Discs form symphyses between bodies covered by hyaline cartilage end plates."],["In an adult, the dural sac ends at:",["L1","L3","S2","Coccyx"],2,"The dura and arachnoid end at S2; the cord ends at L1-L2."]]
},
{
  id:"ah-sternum-ribs-joints", title:"Sternum, ribs, costovertebral and sternocostal joints", subject:"Anatomy", region:"Thorax",
  stages:"steps",
  aliases:["sternum","typical rib","first rib","costovertebral joint","costotransverse joint","sternocostal joint","sternal angle"],
  simple:"The chest cage is built from 12 thoracic vertebrae behind, 12 pairs of ribs at the sides and the sternum in front. Ribs join the spine at two small joints and join the sternum through costal cartilages. These joints let the ribs swing up and out during breathing.",
  flow:["Sternum: manubrium, body, xiphoid process","Ribs: 1-7 true, 8-10 false, 11-12 floating","Typical rib: head, neck, tubercle, angle, shaft, costal groove","Costovertebral joints: head joint and costotransverse joint","Sternocostal joints: rib 1 cartilaginous, 2-7 synovial","Fractures, cervical rib and sternotomy guide care"],
  exam:[
    {h:"Sternum", p:["Flat bone: manubrium, body and xiphoid process.","Sternal angle (of Louis): manubriosternal joint, a secondary cartilaginous joint, at the level of the 2nd costal cartilage and T4-T5 disc; landmark for counting ribs, tracheal bifurcation and arch of aorta.","Jugular notch lies at the level of T2-T3; xiphisternal joint at T9. Red marrow in adults allows sternal marrow aspiration."]},
    {h:"Ribs", p:["12 pairs: true ribs 1-7 reach the sternum by their own cartilage; false 8-10 join the cartilage above; floating 11-12 end free.","Typical rib (3-9): head with two facets and a crest, neck, tubercle (articular and non-articular parts), angle, shaft with costal groove housing vein, artery and nerve from above down.","Atypical: rib 1 (shortest, broadest, flattened, single facet, scalene tubercle, grooves for subclavian vein in front and artery behind), rib 2 (tuberosity for serratus anterior), ribs 10-12 (single facet; 11 and 12 have no neck or tubercle)."]},
    {h:"Costovertebral joints", p:["Joint of head of rib: synovial plane joint; typical heads meet the demifacets of their own vertebra and the one above plus the disc; intra-articular ligament splits it into two cavities; radiate ligament in front.","Costotransverse joint: tubercle with transverse process of the same vertebra; synovial plane; supported by costotransverse, superior and lateral costotransverse ligaments.","Ribs 1, 10, 11, 12 have single-cavity head joints; ribs 11 and 12 have no costotransverse joint."]},
    {h:"Sternocostal and related joints", p:["1st sternocostal joint: primary cartilaginous (synchondrosis), giving stability to the manubrium.","2nd-7th: synovial plane joints; the 2nd has two cavities separated by an intra-articular ligament.","Costochondral joints are primary cartilaginous; interchondral joints (6th-9th cartilages) are synovial plane."]},
    {h:"Applied anatomy and physiotherapy relevance", p:["Rib fractures occur near the angle, the weakest point; multiple segmental fractures cause flail chest with paradoxical movement.","Cervical rib (from C7) can compress the lower trunk of brachial plexus and subclavian artery (thoracic outlet syndrome).","After median sternotomy, sternal precautions limit heavy pushing and lifting; supported coughing protects the wound.","Physiotherapy: pain control, breathing exercises, incentive spirometry and thoracic mobility after rib fracture or chest surgery; costochondritis is managed with reassurance and load modification."]},
    {h:"Conclusion", p:["The sternum, ribs and their joints form a mobile cage whose structure explains breathing mechanics and chest injuries."]}
  ],
  tip:"Draw a typical rib from behind (head, neck, tubercle, angle, costal groove) beside a thoracic vertebra showing the head and costotransverse joints.",
  evidence:[["Incentive spirometry and breathing exercises after rib fracture","Commonly used to prevent pulmonary complications; trial evidence limited","Low"],["Surgical rib fixation for flail chest","May reduce ventilator time in selected patients","Moderate"],["Modified (less restrictive) sternal precautions","Early studies show safe recovery with patient-guided activity","Low-moderate"]],
  evidenceSource:"B D Chaurasia; reviews on rib fixation and sternal precautions",
  outcomes:[["Chest expansion with tape","Thoracic cage mobility"],["NPRS on coughing","Pain limiting ventilation"],["SpO2 and incentive spirometer volume","Respiratory function after injury"]],
  recent:["Several cardiac surgery units now use less restrictive, patient-guided sternal precautions instead of strict lifting bans."],
  mnemonic:{word:"7-3-2", items:[["7","True ribs (1-7)"],["3","False ribs (8-10)"],["2","Floating ribs (11-12)"]], extra:"Count ribs from the sternal angle, where rib 2 joins."},
  example:"A 58-year-old auto driver in Chennai has two fractured left ribs after a crash. He takes shallow breaths and avoids coughing; the physiotherapist teaches supported coughing and deep breathing.",
  flags:["Paradoxical chest movement after trauma (flail chest)","Breathlessness with absent breath sounds (pneumothorax or haemothorax)","Sternal clicking or wound discharge after sternotomy (instability or infection)"],
  viva:[["At what level is the sternal angle?","2nd costal cartilage, T4-T5 disc."],["Which sternocostal joint is cartilaginous?","The first."],["Which ribs lack costotransverse joints?","Ribs 11 and 12."]],
  refs:[{c:"Chaurasia BD. Human Anatomy, Volume 1: Upper Limb and Thorax. Chapter: Bones and joints of thorax."},{b:"levangie",ch:"The thorax and chest wall"},{b:"neumann",ch:"Kinematics of ventilation"}],
  keywords:"sternum ribs costovertebral costotransverse sternocostal joints",
  mcq:[["The joint between the first rib and manubrium is:",["Synovial plane","Primary cartilaginous","Secondary cartilaginous","Fibrous"],1,"The 1st sternocostal joint is a synchondrosis."],["The scalene tubercle is a feature of:",["2nd rib","12th rib","1st rib","10th rib"],2,"Scalenus anterior inserts on the scalene tubercle of the first rib."]]
},
{
  id:"ah-intercostal-space", title:"Intercostal spaces, muscles and nerves", subject:"Anatomy", region:"Thorax",
  stages:"steps",
  aliases:["intercostal muscles","intercostal nerve","typical intercostal nerve","intercostal space contents","neurovascular bundle","intercostobrachial"],
  simple:"The gaps between ribs are filled by three thin layers of intercostal muscles, with a nerve, artery and vein running in a groove under each rib. The muscles help breathing and keep the space firm. Knowing where the bundle lies tells you where to put a chest drain safely.",
  flow:["11 spaces, each with three muscle layers","External intercostal fibres run down and forward","Internal intercostal fibres run down and back","Bundle (VAN) lies between internal and innermost layers","Intercostal nerves T1-T11; subcostal T12","Chest drain above rib; zoster follows a nerve"],
  exam:[
    {h:"Introduction", p:["Eleven intercostal spaces lie between the 12 ribs; each contains muscles, membranes, the intercostal nerve, posterior and anterior intercostal vessels and lymphatics."]},
    {h:"Intercostal muscles", p:["External intercostal: lower border of rib above to upper border of rib below; fibres downward and forward; from tubercle to costochondral junction, then replaced by the external intercostal membrane.","Internal intercostal: fibres downward and backward; from sternum to angle, then replaced by the internal intercostal membrane.","Innermost layer: innermost intercostal (middle part), subcostalis (posteriorly) and transversus thoracis (anteriorly).","Nerve supply: intercostal nerves of the space."]},
    {h:"Actions", p:["External intercostals and the interchondral part of internal intercostals elevate ribs in inspiration.","Interosseous part of internal intercostals depresses ribs in forced expiration.","All layers stiffen the space so it does not suck in or bulge out with pressure changes."]},
    {h:"Intercostal nerves", p:["Ventral rami of T1-T11; T12 is the subcostal nerve. They run in the costal groove between internal and innermost layers, below the vessels (vein, artery, nerve from above).","Typical nerve (T3-T6): muscular branches, collateral branch, lateral cutaneous and anterior cutaneous branches.","Atypical: T1 (most fibres join the brachial plexus), T2 (lateral cutaneous branch is the intercostobrachial nerve to the medial arm), T7-T11 (thoracoabdominal nerves supplying the abdominal wall; T10 at the umbilicus)."]},
    {h:"Intercostal vessels", p:["Posterior intercostal arteries: spaces 1-2 from the superior intercostal (costocervical trunk), 3-11 from the descending thoracic aorta.","Anterior intercostal arteries: spaces 1-6 from internal thoracic, 7-9 from musculophrenic; none in spaces 10-11.","Veins drain to the azygos system behind and internal thoracic veins in front."]},
    {h:"Applied anatomy and physiotherapy relevance", p:["Chest drain or aspiration is placed just above the upper border of the lower rib, in the triangle of safety (about 5th space, mid-axillary line), to avoid the bundle.","Herpes zoster gives a band of pain and rash along one intercostal nerve; intercostal nerve block relieves rib fracture pain.","In high spinal cord injury the intercostals are paralysed, so the chest wall may move paradoxically and breathing relies on the diaphragm.","Physiotherapy: segmental expansion exercises using hand pressure over the ribs, intercostal stretching and thoracic mobility after surgery."]},
    {h:"Conclusion", p:["The layered muscles and the neurovascular bundle under each rib explain breathing, chest wall pain and safe procedures."]}
  ],
  tip:"Draw a coronal section of one space showing three muscle layers, the costal groove and the vein-artery-nerve order, with a needle entering above the lower rib.",
  evidence:[["Intercostal or paravertebral nerve block after rib fracture","Improves pain and ability to breathe deeply","Moderate"],["Inspiratory muscle training in tetraplegia","May improve inspiratory muscle strength","Low-moderate"]],
  evidenceSource:"B D Chaurasia; reviews on analgesia for rib fractures and respiratory muscle training in spinal cord injury",
  outcomes:[["Chest expansion","Mobility of the rib cage"],["Maximal inspiratory pressure (MIP)","Inspiratory muscle strength"],["Dermatomal sensory testing","Level of intercostal nerve involvement"]],
  recent:["Ultrasound-guided chest wall blocks (such as serratus anterior plane block) are increasingly used for rib fracture pain."],
  mnemonic:{word:"VAN", items:[["V","Vein highest"],["A","Artery"],["N","Nerve lowest and most exposed"]], extra:"So needles go just above the rib below."},
  example:"A 70-year-old woman in Kochi develops burning pain and a band of blisters around the right side of her chest at nipple level, matching the T4 intercostal nerve.",
  flags:["Sudden breathlessness after chest procedure (pneumothorax)","Chest wall pain with exertional breathlessness or sweating (exclude cardiac cause)","Rash near the eye with zoster (ophthalmic zoster, urgent)"],
  viva:[["Direction of external intercostal fibres?","Downward and forward, like hands in the front pockets."],["Name the lateral cutaneous branch of T2.","Intercostobrachial nerve."],["Where do you insert a chest drain?","Above the upper border of the rib below, in the triangle of safety."]],
  refs:[{c:"Chaurasia BD. Human Anatomy, Volume 1: Upper Limb and Thorax. Chapter: Wall of thorax."},{b:"frownfelter",ch:"Anatomy and physiology of the respiratory system"},{b:"neumann",ch:"Kinematics of ventilation"}],
  keywords:"intercostal muscles nerves vessels space anatomy",
  mcq:[["The neurovascular bundle lies between:",["External and internal intercostals","Internal and innermost intercostals","Innermost intercostal and pleura","Skin and external intercostal"],1,"The bundle runs in the plane between internal and innermost layers."],["The anterior intercostal arteries of spaces 7-9 come from:",["Internal thoracic","Superior epigastric","Musculophrenic","Thoracic aorta"],2,"The musculophrenic artery supplies spaces 7-9 anteriorly."]]
},
{
  id:"ah-diaphragm", title:"Diaphragm: attachments, nerve supply, openings and actions", subject:"Anatomy", region:"Thorax",
  stages:"steps",
  aliases:["diaphragm","phrenic nerve","caval opening","oesophageal hiatus","aortic opening","diaphragmatic hernia"],
  simple:"The diaphragm is a dome-shaped sheet of muscle that separates chest from abdomen and is the main muscle of breathing. When it contracts it moves down and pulls air in. It is supplied by the phrenic nerve from C3, C4 and C5, and important tubes pass through its openings.",
  flow:["Origin: sternal, costal and vertebral (crura and arcuate ligaments) parts","Insertion: central tendon","Motor supply: phrenic nerve C3, C4, C5","Openings: IVC at T8, oesophagus at T10, aorta at T12","Contracts to increase vertical chest diameter","Palsy, hernia and referred shoulder pain are key applied points"],
  exam:[
    {h:"Introduction", p:["Musculotendinous dome between thorax and abdomen; right dome higher (about 5th rib) than left (5th intercostal space) at rest because of the liver.","The chief muscle of inspiration."]},
    {h:"Origin and insertion", p:["Sternal part: two slips from the back of the xiphoid process.","Costal part: inner surfaces of lower 6 costal cartilages and ribs, interdigitating with transversus abdominis.","Vertebral part: right crus from L1-L3 bodies and discs, left crus from L1-L2; median arcuate ligament joins the crura over the aorta; medial arcuate over psoas (body to transverse process of L1); lateral arcuate over quadratus lumborum (L1 transverse process to 12th rib).","Insertion: trefoil-shaped central tendon, fused with the fibrous pericardium above."]},
    {h:"Nerve and blood supply", p:["Motor: phrenic nerves (ventral rami C3, C4, C5), each supplying its own half including the crura.","Sensory: central part by phrenic nerve; peripheral part by lower 6 intercostal nerves.","Arteries: superior and inferior phrenic, musculophrenic and pericardiacophrenic."]},
    {h:"Openings", p:["Caval opening at T8 in the central tendon: IVC and branches of right phrenic nerve.","Oesophageal opening at T10 in the right crus: oesophagus, anterior and posterior vagal trunks, oesophageal branches of left gastric vessels.","Aortic opening at T12 behind the median arcuate ligament: aorta, thoracic duct, azygos vein.","Other passages: splanchnic nerves pierce the crura, sympathetic trunk passes behind the medial arcuate ligament, superior epigastric vessels pass between sternal and costal slips."]},
    {h:"Actions", p:["Contraction flattens the domes, increasing vertical diameter of the thorax; in quiet breathing it moves about 1.5 cm and in deep breathing several centimetres.","With the abdominal viscera acting as a fulcrum, it also lifts the lower ribs (bucket handle) through the zone of apposition.","Raises intra-abdominal pressure for coughing, vomiting, defecation, childbirth and spinal stability; the right crus acts as a sphincter at the oesophagus."]},
    {h:"Applied anatomy and physiotherapy relevance", p:["Phrenic palsy causes paradoxical upward movement of the paralysed dome on sniffing; cord injury above C3 needs ventilation, while C4-C5 injuries keep partial diaphragm function.","Hernias: congenital posterolateral (Bochdalek), anterior (Morgagni), and acquired hiatus hernia.","Diaphragmatic pleura and peritoneum irritation is referred to the shoulder tip (C4 dermatome).","In COPD the diaphragm is flattened with a small zone of apposition, so it works poorly; physiotherapy uses positioning (forward lean), diaphragmatic breathing, inspiratory muscle training and pacing."]},
    {h:"Conclusion", p:["Accurate knowledge of the diaphragm's attachments, C3-C5 supply and openings explains breathing, hernias and respiratory care in spinal injury."]}
  ],
  tip:"Draw the diaphragm from below showing sternal, costal and crural origins, the three arcuate ligaments, central tendon and three openings labelled T8, T10, T12.",
  evidence:[["Inspiratory muscle training in COPD","Improves inspiratory muscle strength and may reduce breathlessness","Moderate"],["Diaphragmatic breathing in COPD","Variable benefit; may worsen efficiency in severe hyperinflation","Low"],["Diaphragm ultrasound in ICU","Helps assess weaning readiness","Moderate"]],
  evidenceSource:"Guyton physiology; B D Chaurasia; Cochrane and ERS reviews on inspiratory muscle training",
  outcomes:[["Maximal inspiratory pressure","Diaphragm and inspiratory strength"],["Sniff test (fluoroscopy or ultrasound)","Paralysis of one hemidiaphragm"],["Diaphragm thickening fraction on ultrasound","Contractile function"]],
  recent:["Bedside ultrasound of diaphragm excursion and thickening is now widely used in ICUs to judge weaning from ventilation."],
  mnemonic:{word:"I 8 10 Eggs At 12", items:[["I 8","IVC at T8"],["10 Eggs","Oesophagus at T10"],["At 12","Aorta at T12"]], extra:"C3, 4, 5 keeps the diaphragm alive."},
  example:"A 24-year-old man in Pune with a C5 complete spinal cord injury after diving breathes with his diaphragm only; his abdomen rises and chest wall sinks on inspiration.",
  flags:["Sudden breathlessness after neck surgery or central line (phrenic injury)","Rapidly falling vital capacity in Guillain-Barre syndrome (respiratory failure risk)","Shoulder tip pain with abdominal pain after trauma (blood under the diaphragm)"],
  viva:[["Root value of phrenic nerve?","C3, C4, C5, mainly C4."],["What passes through the aortic opening?","Aorta, thoracic duct and azygos vein."],["Why is shoulder pain felt in diaphragm irritation?","Phrenic nerve (C4) shares segments with the supraclavicular nerves supplying the shoulder skin."]],
  refs:[{c:"Chaurasia BD. Human Anatomy, Volume 2: Lower Limb, Abdomen and Pelvis. Chapter: Diaphragm."},{b:"guyton",ch:"Pulmonary ventilation"},{b:"frownfelter",ch:"Anatomy and physiology of the respiratory system"}],
  keywords:"diaphragm attachments phrenic nerve openings actions",
  mcq:[["The oesophageal opening lies at the level of:",["T8","T10","T12","L1"],1,"It lies at T10 in the muscular right crus."],["Sensory supply to the peripheral part of the diaphragm is from:",["Phrenic nerve","Vagus","Lower intercostal nerves","Splanchnic nerves"],2,"The periphery is supplied by the lower 6 intercostal nerves."]]
},
{
  id:"ah-rib-movements", title:"Movements of ribs: pump handle and bucket handle", subject:"Anatomy", region:"Thorax",
  stages:"steps",
  aliases:["pump handle movement","bucket handle movement","caliper movement","mechanism of respiration","thoracic diameters","rib movements"],
  simple:"When we breathe in, the chest gets bigger in three directions. Upper ribs move forward and up like a pump handle, lower ribs swing up and out like a bucket handle, and the diaphragm moves down. These changes lower the pressure inside so air flows in.",
  flow:["Inspiration enlarges thorax in three diameters","Upper ribs (2-6): pump handle raises AP diameter","Lower ribs (7-10): bucket handle raises transverse diameter","Ribs 11-12: caliper movement; diaphragm raises vertical diameter","Quiet expiration is passive elastic recoil","Chest expansion and segmental breathing use this knowledge"],
  exam:[
    {h:"Introduction", p:["Ventilation needs changes in thoracic volume: anteroposterior, transverse and vertical diameters increase in inspiration.","Rib movement occurs at the costovertebral and costotransverse joints and is transmitted through the sternocostal joints."]},
    {h:"Pump handle movement", p:["Occurs mainly in ribs 2-6 (upper ribs).","Axis passes along the neck of the rib through the head and costotransverse joints; the costotransverse facets on upper thoracic transverse processes are cupped and face forward, allowing rotation of the neck.","The anterior end of the rib and the sternum move upward and forward, increasing the anteroposterior diameter."]},
    {h:"Bucket handle movement", p:["Occurs mainly in ribs 7-10 (lower ribs), whose costotransverse facets are flat and face upward, allowing gliding.","Axis runs from the costovertebral joint behind to the sternum in front; the middle of the rib, which hangs lower, swings upward and outward.","This increases the transverse diameter of the lower thorax."]},
    {h:"Other movements", p:["Ribs 11-12: caliper (pincer) movement outward, steadied by quadratus lumborum.","First rib moves with the manubrium in a small pump handle motion.","Vertical diameter increases by descent of the diaphragm, the largest contributor in quiet breathing."]},
    {h:"Muscles of respiration", p:["Quiet inspiration: diaphragm (C3-C5), external intercostals, interchondral internal intercostals.","Forced inspiration adds scalenes, sternocleidomastoid, pectoralis minor and major, serratus anterior, latissimus dorsi (with arms fixed).","Quiet expiration is passive recoil; forced expiration uses rectus abdominis, obliques, transversus abdominis and internal intercostals."]},
    {h:"Applied anatomy and physiotherapy relevance", p:["Chest expansion is measured with a tape at the axilla (upper, pump handle), nipple or xiphoid level and lower costal margin (bucket handle).","Reduced expansion occurs in ankylosing spondylitis (costovertebral fusion), pleural thickening and pain after surgery.","Segmental (localised) expansion exercises place hands over the upper chest for apical expansion or lateral lower ribs for basal expansion.","In hyperinflated COPD the lower ribs may move inward on inspiration (Hoover sign)."]},
    {h:"Conclusion", p:["Pump handle and bucket handle movements explain how thoracic volume changes and form the basis of chest assessment and breathing exercises."]}
  ],
  tip:"Draw a side view of an upper rib with arrows showing the front end rising (pump handle) and a front view of a lower rib with the middle swinging out (bucket handle), marking each axis.",
  evidence:[["Thoracic expansion exercises after surgery","Part of standard care; added value over early mobilisation is uncertain","Low"],["Exercise and mobility programs in ankylosing spondylitis","Improve spinal mobility and function","Moderate"]],
  evidenceSource:"B D Chaurasia; Levangie and Norkin; Cochrane review on physiotherapy in ankylosing spondylitis",
  outcomes:[["Chest expansion at three levels","Upper versus lower rib movement"],["Respiratory rate and pattern observation","Use of accessory muscles"],["Spirometry (FVC)","Effect on ventilated volume"]],
  recent:["Optoelectronic plethysmography in research now measures volume changes of upper chest, lower chest and abdomen separately."],
  mnemonic:{word:"Pump Up, Bucket Below", items:[["Pump","Upper ribs, AP diameter"],["Bucket","Lower ribs, transverse diameter"],["Piston","Diaphragm, vertical diameter"]], extra:"Caliper for ribs 11-12."},
  example:"A 28-year-old man in Hyderabad with ankylosing spondylitis has reduced chest expansion at all levels. The physiotherapist adds deep breathing with thoracic extension to his daily routine.",
  flags:["Asymmetric or absent expansion on one side (pneumothorax, effusion, collapse)","Paradoxical movement of a chest segment (flail chest)","Breathlessness at rest with accessory muscle use (respiratory distress)"],
  viva:[["Which diameter does pump handle movement increase?","Anteroposterior."],["Why do lower ribs show bucket handle movement?","Their costotransverse facets are flat and face upward, allowing gliding, and the middle of the rib hangs lower than its ends."],["Is quiet expiration active?","No, it is passive elastic recoil."]],
  refs:[{c:"Chaurasia BD. Human Anatomy, Volume 1: Upper Limb and Thorax. Chapter: Joints of thorax and respiratory movements."},{b:"levangie",ch:"The thorax and chest wall"},{b:"frownfelter",ch:"Breathing exercises"}],
  keywords:"pump handle bucket handle rib movements respiration mechanism",
  mcq:[["Bucket handle movement mainly increases the:",["Vertical diameter","Anteroposterior diameter","Transverse diameter","Thoracic outlet"],2,"Lower ribs swing outward, widening the transverse diameter."],["Pump handle movement is seen chiefly in ribs:",["2-6","7-10","11-12","1 only"],0,"Upper ribs rotate about the axis of the neck, lifting the sternum forward."]]
},
{
  id:"ah-heart", title:"Heart: chambers, blood supply and conducting system", subject:"Anatomy", region:"Thorax",
  stages:"steps",
  aliases:["heart anatomy","coronary arteries","conducting system","SA node","chambers of heart","coronary circulation"],
  simple:"The heart is a four-chambered muscular pump in the middle of the chest. Its own muscle is fed by the right and left coronary arteries, and blockage of these causes a heart attack. A special conducting system starting at the SA node sets the beat and spreads it so the chambers squeeze in order.",
  flow:["Heart lies in middle mediastinum inside pericardium","Right atrium and ventricle pump to lungs","Left atrium and ventricle pump to body","Coronary arteries from aortic sinuses supply muscle","SA node to AV node to bundle of His to Purkinje fibres","Infarction, block and cardiac rehab are applied points"],
  exam:[
    {h:"Introduction", p:["Conical muscular organ in the middle mediastinum, enclosed in fibrous and serous pericardium; apex in the left 5th intercostal space about 9 cm from the midline.","Four chambers with four valves: tricuspid, pulmonary, mitral and aortic."]},
    {h:"Chambers", p:["Right atrium: openings of SVC, IVC and coronary sinus; crista terminalis separates rough musculi pectinati from smooth sinus venarum; fossa ovalis in septum is the fetal foramen ovale remnant.","Right ventricle: tricuspid valve with chordae and papillary muscles, trabeculae carneae, septomarginal trabecula (moderator band) carrying the right bundle branch, smooth infundibulum leading to the pulmonary valve.","Left atrium: four pulmonary veins enter; left ventricle: wall about three times thicker than the right, mitral (bicuspid) valve and aortic vestibule."]},
    {h:"Blood supply", p:["Right coronary artery from the anterior aortic sinus: SA nodal branch (in most people), right marginal, AV nodal, and usually the posterior interventricular artery (right dominance).","Left coronary artery from the left posterior aortic sinus: anterior interventricular (left anterior descending) and circumflex branches.","Veins: great, middle and small cardiac veins drain to the coronary sinus into the right atrium; anterior cardiac veins and venae cordis minimae open directly.","Coronary flow occurs mainly in diastole."]},
    {h:"Conducting system", p:["SA node: at the upper end of the crista terminalis near the SVC opening; natural pacemaker at about 60-100 per minute.","AV node: in the interatrial septum near the coronary sinus opening; delays the impulse so atria empty first.","AV bundle (of His) pierces the fibrous skeleton, divides into right and left bundle branches on the septum, then Purkinje fibres in the ventricular walls; ventricles alone beat at about 20-40 per minute."]},
    {h:"Nerve supply", p:["Sympathetic (T1-T5 segments) increases rate and force; parasympathetic (vagus) slows the rate.","Cardiac pain travels with sympathetic fibres to T1-T5, so it is referred to the chest, left arm and medial forearm."]},
    {h:"Applied anatomy and physiotherapy relevance", p:["Left anterior descending occlusion is the commonest cause of anterior wall infarction; right coronary occlusion may cause inferior infarction and heart block.","Heart block and arrhythmias may need pacemakers; check device and avoid strong electrotherapy currents near it.","Cardiac rehabilitation: phase I early mobilisation, phase II supervised aerobic training at about 40-80 percent heart rate reserve or RPE 11-14, 3-5 days a week, 20-60 minutes.","Monitor heart rate, blood pressure, symptoms and RPE; stop exercise with chest pain, dizziness or abnormal BP response."]},
    {h:"Conclusion", p:["Chambers, coronary supply and the conducting system together explain cardiac pain, infarction patterns and the safe design of exercise."]}
  ],
  tip:"Draw the heart from the front with coronary arteries, then a separate opened view showing SA node, AV node, bundle of His and bundle branches.",
  evidence:[["Exercise-based cardiac rehabilitation after MI","Reduces cardiovascular mortality and hospital admission, improves quality of life","High"],["Home-based vs centre-based cardiac rehab","Similar outcomes in low-risk patients","Moderate"]],
  evidenceSource:"Cochrane review of exercise-based cardiac rehabilitation (Dibben et al. 2021); ACSM guidelines",
  outcomes:[["Six-minute walk test","Functional capacity"],["Borg RPE","Exercise intensity"],["Heart rate and BP response","Safety during exercise"]],
  recent:["Leadless pacemakers implanted directly into the right ventricle are now in clinical use."],
  mnemonic:{word:"SA-AV-His-BB-P", items:[["SA","Sinoatrial node (pacemaker)"],["AV","Atrioventricular node (delay)"],["His","AV bundle"],["BB","Right and left bundle branches"],["P","Purkinje fibres"]], extra:"Say it as 'Sita And Vani Hire Big Pandals'."},
  example:"A 55-year-old shop owner in Lucknow has an anterior wall MI from LAD block. After stenting, he joins a phase II program walking on a treadmill at RPE 12-13.",
  flags:["Chest pain at rest or new arrhythmia during exercise (stop and seek medical help)","Systolic BP falls with rising workload","Resting heart rate above about 120 or uncontrolled hypertension (defer exercise)"],
  viva:[["Where is the SA node?","Upper end of crista terminalis near the SVC opening in the right atrium."],["Which artery is called the widow maker?","Left anterior descending (anterior interventricular) artery."],["What does the moderator band carry?","The right bundle branch."]],
  refs:[{c:"Chaurasia BD. Human Anatomy, Volume 1: Upper Limb and Thorax. Chapter: Heart."},{b:"guyton",ch:"Rhythmical excitation of the heart"},{b:"acsm",ch:"Cardiac rehabilitation"}],
  keywords:"heart chambers coronary arteries conducting system anatomy",
  mcq:[["The posterior interventricular artery most commonly arises from the:",["Left anterior descending","Circumflex","Right coronary artery","Internal thoracic"],2,"Most hearts are right dominant."],["The impulse is delayed to allow atrial emptying at the:",["SA node","AV node","Purkinje fibres","Bundle branches"],1,"The AV node delays conduction to the ventricles."]]
},
{
  id:"ah-respiratory-tract-pleura", title:"Respiratory tract, pleura and bronchopulmonary segments", subject:"Anatomy", region:"Thorax",
  stages:"steps",
  aliases:["bronchopulmonary segments","pleura","bronchial tree","lungs lobes","trachea","postural drainage anatomy"],
  simple:"Air travels through nose, pharynx, larynx, trachea and branching bronchi to the alveoli. Each lung is wrapped in a double layer of pleura with a thin film of fluid between. Each lung is divided into segments supplied by their own bronchus, which is why we can drain or remove one segment at a time.",
  flow:["Upper tract: nose, pharynx, larynx","Trachea divides at T4-T5 into main bronchi","Right main bronchus wider, shorter, more vertical","Lungs: right 3 lobes, left 2 lobes","Pleura: visceral and parietal with pleural cavity","10 segments per lung guide postural drainage"],
  exam:[
    {h:"Respiratory tract", p:["Upper: nose, paranasal sinuses, pharynx, larynx; lower: trachea, bronchi, bronchioles, alveoli.","Trachea: from C6 to the sternal angle (T4-T5), about 10-11 cm, with C-shaped cartilage rings open behind (trachealis muscle); carina at the bifurcation.","Right main bronchus is shorter, wider and more vertical than the left, so aspirated objects usually enter the right lung, especially the lower lobe.","Branching: main, lobar, segmental bronchi, bronchioles, terminal and respiratory bronchioles, alveolar ducts and alveoli."]},
    {h:"Lungs", p:["Right lung: three lobes by oblique and horizontal fissures; left lung: two lobes by oblique fissure, with cardiac notch and lingula.","Hilum: bronchus, pulmonary artery, pulmonary veins, bronchial vessels, nerves and lymphatics."]},
    {h:"Pleura", p:["Visceral pleura covers the lung and dips into fissures; parietal pleura lines the wall in costal, diaphragmatic, mediastinal and cervical (cupola) parts.","Pleural cavity holds a thin film of fluid that allows gliding and keeps lungs stuck to the wall; recesses: costodiaphragmatic and costomediastinal.","Lower borders: lung at 6th rib midclavicular, 8th midaxillary, 10th near spine; pleura two ribs lower (8th, 10th, 12th).","Parietal pleura is pain sensitive (intercostal and phrenic nerves); visceral pleura is insensitive to pain."]},
    {h:"Bronchopulmonary segments", p:["Definition: a pyramidal, well-defined part of lung aerated by a segmental (tertiary) bronchus with its own segmental artery; veins run between segments; apex toward hilum.","Right lung (10): upper lobe - apical, posterior, anterior; middle lobe - lateral, medial; lower lobe - superior (apical), medial basal, anterior basal, lateral basal, posterior basal.","Left lung (usually 8-10): upper lobe - apicoposterior, anterior, superior lingular, inferior lingular; lower lobe - superior, anteromedial basal, lateral basal, posterior basal."]},
    {h:"Applied anatomy and physiotherapy relevance", p:["Postural drainage positions place the segmental bronchus vertical: upper lobe apical segments in upright sitting; superior segments of lower lobes in prone lying flat; basal segments in head-down tilt of about 20 degrees where tolerated.","Middle lobe and lingula: supine quarter turned with head-down tilt of about 15 degrees; head-down positions are avoided in raised ICP, recent surgery, haemoptysis and severe GERD.","Pleural effusion collects first in the costodiaphragmatic recess; pneumothorax collapses the lung; segmental resection is possible because segments are independent.","Airway clearance: active cycle of breathing, percussion, vibrations, PEP devices, combined with drainage positions."]},
    {h:"Conclusion", p:["Knowing the tract, pleura and segments lets a physiotherapist localise disease and position patients for effective airway clearance."]}
  ],
  tip:"Draw the bronchial tree from the front with right and left segmental bronchi numbered, and a transverse section showing visceral and parietal pleura with the pleural cavity.",
  evidence:[["Airway clearance techniques in cystic fibrosis and bronchiectasis","Help sputum clearance; no single technique clearly superior","Moderate"],["Head-down postural drainage in infants","Linked to reflux; modified positions preferred","Moderate"]],
  evidenceSource:"Frownfelter; Cochrane reviews of airway clearance techniques; BTS bronchiectasis guideline",
  outcomes:[["Sputum weight or volume","Effect of airway clearance"],["Auscultation and chest X-ray","Segment involved"],["SpO2 and breathlessness score","Tolerance to position"]],
  recent:["British Thoracic Society bronchiectasis guidelines (2019) recommend that patients are taught an airway clearance technique by a respiratory physiotherapist."],
  mnemonic:{word:"A PAL MA SMALL P", items:[["A P A","Right upper: apical, posterior, anterior"],["L M","Right middle: lateral, medial"],["S M A L P","Right lower: superior, medial, anterior, lateral, posterior basal"]], extra:"Left side merges apicoposterior and anteromedial basal."},
  example:"A 10-year-old boy in Delhi swallows a peanut while laughing and develops cough and wheeze on the right side; the nut has lodged in the right lower lobe bronchus.",
  flags:["Haemoptysis (avoid percussion and head-down drainage)","Sudden pleuritic chest pain with breathlessness (pneumothorax or embolus)","Raised intracranial pressure or unstable BP (avoid head-down tilt)"],
  viva:[["Define bronchopulmonary segment.","A part of lung aerated by a segmental bronchus with its own artery, separated by connective tissue, surgically resectable."],["Why do foreign bodies enter the right bronchus?","It is wider, shorter and more vertical."],["Which pleura is pain sensitive?","Parietal pleura."]],
  refs:[{c:"Chaurasia BD. Human Anatomy, Volume 1: Upper Limb and Thorax. Chapter: Lungs and pleura."},{b:"frownfelter",ch:"Airway clearance techniques"},{b:"guyton",ch:"Pulmonary ventilation"}],
  keywords:"respiratory tract pleura lung lobes bronchopulmonary segments postural drainage",
  mcq:[["How many bronchopulmonary segments does the right lung have?",["8","9","10","12"],2,"Right lung: 3 upper, 2 middle, 5 lower."],["The parietal pleura in the midaxillary line reaches the:",["6th rib","8th rib","10th rib","12th rib"],2,"Pleura lies two ribs below the lung: 8th, 10th, 12th."]]
},
{
  id:"ah-skull-foramina", title:"Skull: foramina and structures passing through", subject:"Anatomy", region:"Head and neck",
  stages:"steps",
  aliases:["skull foramina","base of skull","foramen ovale","jugular foramen","cranial fossae","foramen magnum"],
  simple:"The skull protects the brain, and its base has many holes called foramina through which nerves and vessels enter and leave. Each foramen carries specific structures. A fracture or tumour near a foramen damages exactly those nerves, which helps us localise the lesion.",
  flow:["Skull: cranium (8 bones) and face (14 bones)","Base: anterior, middle, posterior cranial fossae","Anterior fossa: cribriform plate for olfactory nerves","Middle fossa: optic canal, SOF, rotundum, ovale, spinosum","Posterior fossa: IAM, jugular foramen, hypoglossal canal, magnum","Base fractures and foramen lesions give nerve signs"],
  exam:[
    {h:"Introduction", p:["Skull has 22 bones: 8 cranial (frontal, 2 parietal, occipital, 2 temporal, sphenoid, ethmoid) and 14 facial bones, including the mandible.","Sutures: coronal, sagittal and lambdoid; anterior fontanelle closes at about 18 months, posterior at about 2-3 months.","Interior of the base shows three cranial fossae: anterior, middle and posterior."]},
    {h:"Anterior cranial fossa", p:["Cribriform plate of ethmoid: olfactory nerve filaments and anterior ethmoidal nerve and vessels.","Foramen caecum: emissary vein (in children)."]},
    {h:"Middle cranial fossa", p:["Optic canal: optic nerve and ophthalmic artery.","Superior orbital fissure: oculomotor, trochlear, abducent nerves, lacrimal, frontal and nasociliary branches of V1, superior ophthalmic vein.","Foramen rotundum: maxillary nerve (V2). Foramen ovale: mandibular nerve (V3), accessory meningeal artery, lesser petrosal nerve, emissary vein.","Foramen spinosum: middle meningeal artery and meningeal branch of V3. Carotid canal: internal carotid artery with sympathetic plexus; foramen lacerum: filled with cartilage, ICA passes across its upper part."]},
    {h:"Posterior cranial fossa", p:["Internal acoustic meatus: facial (VII), vestibulocochlear (VIII) nerves, labyrinthine artery.","Jugular foramen: glossopharyngeal (IX), vagus (X), accessory (XI) nerves, internal jugular vein (from sigmoid sinus), inferior petrosal sinus.","Hypoglossal canal: hypoglossal nerve (XII).","Foramen magnum: lower medulla and meninges, vertebral arteries, anterior and posterior spinal arteries, spinal roots of accessory nerve, apical and alar ligaments, tectorial membrane."]},
    {h:"Exterior of base", p:["Stylomastoid foramen: facial nerve exits to the face; stylomastoid artery enters.","Mastoid process gives attachment to sternocleidomastoid; occipital condyles articulate with the atlas."]},
    {h:"Applied anatomy and physiotherapy relevance", p:["Fracture of anterior fossa: CSF rhinorrhoea, loss of smell, periorbital (raccoon) bruising; middle fossa: CSF otorrhoea, facial palsy, Battle sign behind the ear.","Pterion overlies the anterior branch of middle meningeal artery; a blow here can cause extradural haematoma with a lucid interval.","Jugular foramen lesion affects IX, X, XI together (swallowing, voice, trapezius and SCM weakness).","Bell palsy involves the facial nerve in the facial canal near the stylomastoid foramen; physiotherapy includes eye protection, facial exercises and education; TBI rehab follows base fractures."]},
    {h:"Conclusion", p:["Linking each foramen with its contents allows exact localisation of cranial nerve lesions after skull base injury or disease."]}
  ],
  tip:"Draw the interior of the skull base as three steps (fossae) and mark each foramen with its contents in a neat table beside it.",
  evidence:[["Corticosteroids within 72 hours in Bell palsy","Improve facial recovery","High"],["Facial exercises in facial palsy","May improve function and reduce synkinesis; evidence low certainty","Low"]],
  evidenceSource:"B D Chaurasia; Cochrane reviews on Bell palsy treatments",
  outcomes:[["House-Brackmann scale","Facial nerve grade"],["Cranial nerve examination","Which foramen is involved"],["Glasgow Coma Scale","Severity of head injury"]],
  recent:["Terminologia Anatomica second edition (2019) updated official anatomical terms used in modern textbooks."],
  mnemonic:{word:"OVALE", items:[["O","Otic ganglion (just below)"],["V","V3 mandibular nerve"],["A","Accessory meningeal artery"],["L","Lesser petrosal nerve"],["E","Emissary vein"]], extra:"Jugular foramen: 9, 10, 11 and IJV."},
  example:"A 30-year-old bike rider in Patna has clear fluid from his nose and bruising around both eyes after a crash, signs of an anterior cranial fossa fracture.",
  flags:["Clear fluid from nose or ear after head injury (CSF leak)","Lucid interval followed by drowsiness (extradural haematoma)","Multiple lower cranial nerve palsies (skull base tumour)"],
  viva:[["What passes through foramen spinosum?","Middle meningeal artery and meningeal branch of mandibular nerve."],["Contents of jugular foramen?","IX, X, XI cranial nerves, IJV and inferior petrosal sinus."],["What leaves through the stylomastoid foramen?","Facial nerve."]],
  refs:[{c:"Chaurasia BD. Human Anatomy, Volume 3: Head and Neck. Chapter: Osteology of the head and neck - skull."},{c:"Standring S, ed. Gray's Anatomy: The Anatomical Basis of Clinical Practice. Chapter: Skull."},{b:"umphred",ch:"Traumatic brain injury"}],
  keywords:"skull foramina base of skull cranial fossae contents",
  mcq:[["The mandibular nerve leaves the skull through the:",["Foramen rotundum","Foramen ovale","Foramen spinosum","Superior orbital fissure"],1,"V3 passes through foramen ovale."],["Which nerve does NOT pass through the jugular foramen?",["Glossopharyngeal","Vagus","Accessory","Hypoglossal"],3,"Hypoglossal nerve passes through the hypoglossal canal."]]
},
{
  id:"ah-triangles-neck", title:"Triangles of the neck", subject:"Anatomy", region:"Head and neck",
  stages:"steps",
  aliases:["anterior triangle","posterior triangle","carotid triangle","digastric triangle","submental triangle","accessory nerve in neck"],
  simple:"The sternocleidomastoid muscle divides each side of the neck into an anterior and a posterior triangle. Each is split into smaller triangles that act like address boxes for important vessels and nerves. Knowing them helps you find pulses and avoid injuring nerves like the accessory nerve.",
  flow:["SCM divides neck into anterior and posterior triangles","Anterior: submental, digastric, carotid, muscular","Carotid triangle holds carotid bifurcation, IJV, vagus, XII","Posterior: occipital and supraclavicular parts","Holds accessory nerve, plexus trunks, subclavian artery","Nerve injury and pulse palpation are applied points"],
  exam:[
    {h:"Introduction", p:["Sternocleidomastoid (origin: manubrium and medial third of clavicle; insertion: mastoid process and superior nuchal line; nerve: spinal accessory with C2-C3 proprioceptive fibres) divides the side of the neck.","Action of SCM: one side tilts the head to the same side and turns the face to the opposite side; both together flex the neck and help forced inspiration."]},
    {h:"Anterior triangle", p:["Boundaries: midline of neck, anterior border of SCM, lower border of mandible; apex at the jugular notch.","Submental (unpaired): anterior bellies of digastric and hyoid; lymph nodes, beginning of anterior jugular veins.","Digastric (submandibular): both bellies of digastric and mandible; submandibular gland, facial artery and vein, hypoglossal and mylohyoid nerves, lymph nodes.","Muscular: midline, superior belly of omohyoid, SCM; infrahyoid muscles, thyroid gland, larynx and trachea deep."]},
    {h:"Carotid triangle", p:["Boundaries: superior belly of omohyoid, posterior belly of digastric and anterior border of SCM.","Contents: common carotid bifurcating at the upper border of thyroid cartilage (C3-C4) into internal and external carotids, branches of external carotid, internal jugular vein, vagus, hypoglossal nerve, ansa cervicalis, sympathetic trunk deep.","Carotid sinus (baroreceptor) and carotid body (chemoreceptor), supplied by the glossopharyngeal nerve."]},
    {h:"Posterior triangle", p:["Boundaries: posterior border of SCM, anterior border of trapezius, middle third of clavicle; roof is investing deep cervical fascia; floor is splenius capitis, levator scapulae and scalenus medius and posterior, covered by prevertebral fascia.","Inferior belly of omohyoid divides it into occipital (upper) and supraclavicular (subclavian) triangles.","Contents: spinal accessory nerve crossing superficially, cutaneous branches of cervical plexus at the midpoint of SCM (lesser occipital, great auricular, transverse cervical, supraclavicular), trunks of brachial plexus, third part of subclavian artery, transverse cervical and suprascapular arteries, external jugular vein, lymph nodes."]},
    {h:"Applied anatomy and physiotherapy relevance", p:["Spinal accessory nerve injury in lymph node biopsy or neck dissection weakens trapezius: shoulder droop, weak abduction above 90 degrees and lateral scapular winging; physiotherapy trains scapular muscles.","Brachial plexus trunks lie in the supraclavicular part; Erb point (C5-C6 junction) injury causes waiter's tip posture.","Carotid pulse is felt at the anterior border of SCM at the level of thyroid cartilage; pressure on the carotid sinus can slow the heart.","Congenital muscular torticollis (SCM fibrosis): head tilted to the same side and turned to the opposite; physiotherapy uses gentle stretching and positioning."]},
    {h:"Conclusion", p:["The triangles organise neck anatomy into regions, guiding palpation, procedures and understanding of nerve injuries."]}
  ],
  tip:"Draw the side of the neck with SCM, trapezius, digastric and omohyoid outlined, shade each triangle, and write the key contents inside each one.",
  evidence:[["Stretching program for congenital muscular torticollis","High success when started early in infancy","Moderate"],["Scapular strengthening after accessory nerve injury","Improves shoulder function; evidence mainly from case series","Low"]],
  evidenceSource:"B D Chaurasia; APTA clinical practice guideline on congenital muscular torticollis (Kaplan et al. 2018)",
  outcomes:[["Cervical rotation and lateral flexion range","Torticollis severity"],["Scapular position and shoulder abduction","Trapezius function"],["Carotid and subclavian pulses","Vascular status"]],
  recent:["The APTA congenital muscular torticollis guideline was updated in 2018 with early referral and home stretching as key recommendations."],
  mnemonic:{word:"SCM splits the neck", items:[["Anterior","Submental, Digastric, Carotid, Muscular"],["Posterior","Occipital, Supraclavicular"],["Divider","Omohyoid splits both"]], extra:"Accessory nerve crosses the posterior triangle superficially."},
  example:"A 40-year-old teacher in Bhopal cannot lift her arm fully overhead after a lymph node biopsy in the posterior triangle; her shoulder droops, suggesting accessory nerve injury.",
  flags:["New neck lump with weight loss or night sweats (lymphoma, metastasis, TB)","Shoulder droop and weakness after neck surgery (nerve injury)","Neck pain with dizziness or visual disturbance (vascular cause)"],
  viva:[["Boundaries of carotid triangle?","Superior belly of omohyoid, posterior belly of digastric, anterior border of SCM."],["Which nerve is at risk in the posterior triangle?","Spinal accessory nerve."],["Level of carotid bifurcation?","Upper border of thyroid cartilage, C3-C4."]],
  refs:[{c:"Chaurasia BD. Human Anatomy, Volume 3: Head and Neck. Chapter: Side of the neck; anterior triangle."},{b:"kendall",ch:"Neck muscles"},{b:"magee",ch:"Cervical spine"}],
  keywords:"triangles of neck anterior posterior carotid digastric",
  mcq:[["Which structure divides the posterior triangle?",["Posterior belly of digastric","Inferior belly of omohyoid","Scalenus anterior","Trapezius"],1,"The inferior belly of omohyoid divides it into occipital and supraclavicular triangles."],["Injury to the spinal accessory nerve in the posterior triangle weakens:",["Serratus anterior","Trapezius","Rhomboids","Levator scapulae"],1,"The nerve supplies trapezius after leaving SCM."]]
},
{
  id:"ah-facial-muscles-cranial-nerves", title:"Facial muscles, cranial nerves and trigeminal nerve", subject:"Anatomy", region:"Head and neck",
  stages:"steps",
  aliases:["muscles of facial expression","cranial nerves","trigeminal nerve","facial nerve palsy","Bell palsy","muscles of mastication"],
  simple:"Muscles of facial expression lie in the skin of the face and are all supplied by the facial nerve. Twelve pairs of cranial nerves come from the brain to supply the head and neck. The trigeminal nerve, the fifth, gives feeling to the face and moves the jaw muscles.",
  flow:["Facial muscles: from 2nd arch, supplied by facial nerve","Groups around eye, nose, mouth, scalp and neck","12 cranial nerves: sensory, motor or mixed","Trigeminal: V1, V2 sensory; V3 mixed","V3 supplies muscles of mastication","UMN vs LMN facial palsy and trigeminal neuralgia applied"],
  exam:[
    {h:"Facial muscles", p:["Develop from the second pharyngeal arch, lie in superficial fascia and insert into skin; all supplied by the facial nerve (VII).","Eye: orbicularis oculi (closes eye; orbital part tight closure, palpebral part blinking), corrugator supercilii (frowning), procerus.","Mouth: orbicularis oris (closes lips), buccinator (presses cheek on teeth, blowing, keeps food between teeth), zygomaticus major (smile), levator labii superioris, depressor anguli oris, risorius, mentalis.","Scalp and neck: occipitofrontalis (raises eyebrows, wrinkles forehead), platysma (depresses mandible, tenses neck skin)."]},
    {h:"Facial nerve", p:["Leaves the skull through stylomastoid foramen and divides in the parotid into temporal, zygomatic, buccal, marginal mandibular and cervical branches.","Also supplies stapedius, posterior belly of digastric, stylohyoid; carries taste from anterior two-thirds of tongue (chorda tympani) and secretomotor fibres to lacrimal, submandibular and sublingual glands."]},
    {h:"Cranial nerves (outline)", p:["I olfactory (smell), II optic (vision), III oculomotor (most eye muscles, pupil constriction, lifts lid), IV trochlear (superior oblique), V trigeminal (face sensation, mastication), VI abducent (lateral rectus).","VII facial (facial expression, taste), VIII vestibulocochlear (hearing, balance), IX glossopharyngeal (taste posterior third, gag sensation), X vagus (palate, pharynx, larynx, viscera), XI accessory (SCM, trapezius), XII hypoglossal (tongue muscles)."]},
    {h:"Trigeminal nerve", p:["Largest cranial nerve; large sensory root and small motor root at the side of the pons; sensory (trigeminal) ganglion in Meckel cave near the petrous apex.","Nuclei: mesencephalic (proprioception), main sensory (touch), spinal nucleus extending to C2 (pain and temperature), motor nucleus.","V1 ophthalmic (superior orbital fissure): forehead, upper lid, cornea, nose; afferent limb of corneal reflex. V2 maxillary (foramen rotundum): cheek, upper lip, upper teeth.","V3 mandibular (foramen ovale): lower face, lower teeth, anterior two-thirds of tongue (general sensation); motor to masseter, temporalis, medial and lateral pterygoids, mylohyoid, anterior belly of digastric, tensor tympani and tensor veli palatini."]},
    {h:"Applied anatomy and physiotherapy relevance", p:["LMN facial palsy (Bell palsy) paralyses the whole half of the face; UMN lesion (stroke) spares the forehead because the upper face has bilateral cortical supply.","Physiotherapy in Bell palsy: eye care, mirror-guided facial exercises, massage, avoid strong mass-movement exercises to reduce synkinesis; electrical stimulation is not routinely recommended.","Trigeminal neuralgia: brief electric shock pain in V2 or V3 triggered by touch or chewing; corneal reflex and jaw jerk test V; herpes zoster commonly affects V1.","Cranial nerve testing is part of neuro assessment in stroke, TBI and GBS."]},
    {h:"Conclusion", p:["Facial muscles, the cranial nerves and especially V and VII are frequently examined because they explain common facial palsies and pain syndromes."]}
  ],
  tip:"Draw the face with the five branches of the facial nerve fanning from the parotid, and a separate outline of the face shaded for V1, V2 and V3 sensory areas.",
  evidence:[["Oral corticosteroids in Bell palsy","Increase complete recovery","High"],["Facial exercise and mirror biofeedback","May improve function and reduce synkinesis","Low"],["Electrical stimulation in acute Bell palsy","Insufficient evidence of benefit","Low"]],
  evidenceSource:"Cochrane reviews of Bell palsy treatment; AAO-HNS Bell palsy guideline (Baugh et al. 2013)",
  outcomes:[["House-Brackmann grade","Facial nerve function"],["Sunnybrook facial grading system","Voluntary movement, symmetry and synkinesis"],["Corneal reflex and jaw jerk","Trigeminal function"]],
  recent:["The Sunnybrook facial grading system is widely used to track synkinesis in facial rehabilitation."],
  mnemonic:{word:"To Zanzibar By Motor Car", items:[["To","Temporal"],["Zanzibar","Zygomatic"],["By","Buccal"],["Motor","Marginal mandibular"],["Car","Cervical"]], extra:"Branches of the facial nerve in the face."},
  example:"A 35-year-old woman in Jaipur wakes up unable to close her right eye or raise her right eyebrow, with drooping of the right mouth corner: a right LMN facial (Bell) palsy.",
  flags:["Facial weakness sparing forehead with limb weakness (stroke, emergency)","Cannot close eye fully (risk of corneal ulcer)","Facial palsy with ear vesicles or hearing loss (Ramsay Hunt syndrome)"],
  viva:[["Nerve supply of buccinator?","Facial nerve (buccal branch), not the buccal branch of V3, which is sensory."],["Why is the forehead spared in UMN facial palsy?","The part of the facial nucleus for the upper face gets bilateral cortical supply."],["Which muscles of mastication open the mouth?","Lateral pterygoids."]],
  refs:[{c:"Chaurasia BD. Human Anatomy, Volume 3: Head and Neck. Chapters: Face; Cranial nerves."},{b:"inderbir",ch:"Cranial nerves"},{b:"umphred",ch:"Cranial nerve disorders"}],
  keywords:"facial muscles cranial nerves trigeminal facial nerve Bell palsy",
  mcq:[["Which muscle is supplied by the mandibular nerve?",["Buccinator","Anterior belly of digastric","Posterior belly of digastric","Stapedius"],1,"V3 supplies anterior belly of digastric; VII supplies the posterior belly."],["Afferent limb of the corneal reflex is carried by:",["Facial nerve","Oculomotor nerve","Ophthalmic nerve","Optic nerve"],2,"V1 (nasociliary branch) carries corneal sensation; VII closes the eye."]]
},
{
  id:"ah-cervical-vertebrae-plexus", title:"Cervical vertebrae, atlas and axis; cervical plexus", subject:"Anatomy", region:"Head and neck",
  stages:"steps",
  aliases:["atlas","axis","dens","cervical vertebra","cervical plexus","phrenic nerve","ansa cervicalis"],
  simple:"The neck has seven cervical vertebrae. The first two, the atlas and axis, are special: the atlas is a ring that carries the skull and the axis has a peg (dens) around which the atlas turns. The ventral rami of C1-C4 form the cervical plexus, which supplies neck skin, neck muscles and the diaphragm through the phrenic nerve.",
  flow:["Typical cervical C3-C6: small body, foramen transversarium, bifid spine","Atlas C1: ring with two lateral masses, no body","Axis C2: dens projects up from body","C7 vertebra prominens: long non-bifid spine","Cervical plexus: ventral rami C1-C4 behind IJV","Cutaneous, muscular and phrenic branches; applied in neck injury"],
  exam:[
    {h:"Typical cervical vertebra (C3-C6)", p:["Small, broad, oval body with upturned lateral lips (uncinate processes) forming uncovertebral joints of Luschka with the body above.","Transverse process has foramen transversarium (vertebral artery C1-C6, vertebral veins, sympathetic plexus) and anterior and posterior tubercles; C6 anterior tubercle is the carotid tubercle.","Large triangular vertebral foramen; short bifid spine; articular facets are flat and face upward-backward (superior) at about 45 degrees."]},
    {h:"Atlas (C1)", p:["Ring-shaped with no body and no spine; anterior arch with anterior tubercle and a facet for the dens behind; posterior arch with posterior tubercle and a groove for the vertebral artery and C1 nerve.","Lateral masses bear kidney-shaped concave superior facets for the occipital condyles and flat circular inferior facets for the axis.","Transverse ligament of atlas runs between tubercles on the medial sides of the lateral masses, holding the dens against the anterior arch; transverse process is long and palpable between mastoid and angle of mandible."]},
    {h:"Axis (C2) and C7", p:["Axis: dens (odontoid process) projects up from the body, representing the body of the atlas; apical ligament at its tip, alar ligaments from its sides to the occipital condyles.","Large flat superior articular facets on the body and pedicles; strong, large bifid spine (first palpable spine below the occiput).","C7 vertebra prominens: long, non-bifid spine giving attachment to ligamentum nuchae; foramen transversarium small and usually without vertebral artery."]},
    {h:"Cervical plexus: formation and position", p:["Formed by ventral rami of C1-C4, lying in front of levator scapulae and scalenus medius, deep to the internal jugular vein and SCM, covered by prevertebral fascia.","Each ramus except the first divides into ascending and descending parts which join as loops."]},
    {h:"Branches", p:["Cutaneous (emerge at the midpoint of the posterior border of SCM, nerve point of the neck): lesser occipital (C2), great auricular (C2, C3), transverse cervical (C2, C3), supraclavicular (C3, C4) nerves.","Muscular: ansa cervicalis (superior root C1 fibres travelling with hypoglossal, inferior root C2-C3) supplies infrahyoid muscles except thyrohyoid (C1 via XII); branches to prevertebral muscles, levator scapulae, scalenus medius; C2-C4 contribute to SCM and trapezius (proprioceptive).","Phrenic nerve (C3, C4, C5): runs down on scalenus anterior, enters thorax behind subclavian vein, motor to diaphragm and sensory to pericardium, mediastinal and diaphragmatic pleura and peritoneum."]},
    {h:"Applied anatomy and physiotherapy relevance", p:["Jefferson (burst) fracture of atlas from axial load; odontoid (dens) fractures and hangman fracture (pars of C2) in hyperextension injuries; physiotherapy must respect collar and surgeon restrictions.","Cervical spondylosis with osteophytes at uncovertebral and facet joints narrows foramina causing radiculopathy (C5-C6, C6-C7 commonest); traction, mobilisation and exercise are used.","Rheumatoid arthritis and Down syndrome weaken the transverse ligament causing atlantoaxial instability; avoid end-range neck manipulation and screen before sport.","Phrenic nerve injury (neck surgery, central lines) paralyses a hemidiaphragm; shoulder tip pain from diaphragm irritation is referred via C4 supraclavicular nerves."]},
    {h:"Conclusion", p:["The special atlas and axis allow head rotation, and the cervical plexus with the phrenic nerve links neck anatomy to breathing."]}
  ],
  tip:"Draw the atlas from above with transverse ligament holding the dens, the axis from the side showing the dens, and a simple loop diagram of C1-C4 rami giving the four cutaneous nerves and phrenic nerve.",
  evidence:[["Exercise plus manual therapy for neck pain","Better short-term pain and function than either alone","Moderate"],["Cervical traction for radiculopathy","Inconsistent additional benefit","Low"],["Canadian C-spine rule","Highly sensitive for excluding significant cervical injury in alert patients","High"]],
  evidenceSource:"B D Chaurasia; Stiell et al. JAMA 2001 (Canadian C-spine rule); Cochrane reviews of neck pain treatment",
  outcomes:[["Neck Disability Index","Neck-related disability"],["Cervical rotation range (CROM)","Upper cervical mobility"],["Flexion-rotation test","C1-C2 rotation mobility"]],
  recent:["Guidelines for neck pain (such as the APTA neck pain guideline revised in 2017) favour combined exercise and manual therapy."],
  mnemonic:{word:"C3, 4, 5 keeps the diaphragm alive", items:[["C2","Lesser occipital"],["C2-3","Great auricular, transverse cervical"],["C3-4","Supraclavicular"],["C3-5","Phrenic"]], extra:"Cutaneous branches all emerge at the midpoint of the posterior border of SCM."},
  example:"A 45-year-old woman in Coimbatore with long-standing rheumatoid arthritis reports neck pain and tingling in both hands on bending her head; flexion-extension X-rays show atlantoaxial instability.",
  flags:["Drop attacks, dizziness or limb tingling on neck movement (instability or vascular cause)","Neck trauma with midline tenderness (imaging before any treatment)","Breathlessness after neck surgery (phrenic injury)"],
  viva:[["What holds the dens in place?","Transverse ligament of atlas (part of the cruciform ligament)."],["Root value of phrenic nerve?","C3, C4, C5."],["What is the nerve point of the neck?","Midpoint of posterior border of SCM where cutaneous branches of the cervical plexus emerge."]],
  refs:[{c:"Chaurasia BD. Human Anatomy, Volume 3: Head and Neck. Chapters: Vertebral column; Deep structures in the neck."},{b:"magee",ch:"Cervical spine"},{b:"neumann",ch:"Axial skeleton: osteology and arthrology"}],
  keywords:"cervical vertebra atlas axis dens cervical plexus phrenic nerve",
  mcq:[["The dens of the axis represents the body of the:",["Axis","Atlas","Occipital bone","C3"],1,"Developmentally the dens is the body of the atlas fused to the axis."],["Which nerve is NOT a cutaneous branch of the cervical plexus?",["Great auricular","Lesser occipital","Greater occipital","Supraclavicular"],2,"The greater occipital nerve is the dorsal ramus of C2."]]
},
{
  id:"ah-atlanto-occipital-axial-joints", title:"Atlanto-occipital and atlantoaxial joints", subject:"Anatomy", region:"Head and neck",
  stages:"steps",
  aliases:["atlanto-occipital joint","atlantoaxial joint","yes joint","no joint","craniovertebral joints","alar ligament","transverse ligament of atlas"],
  simple:"The skull nods on the atlas at the atlanto-occipital joints (the yes joint) and the atlas turns around the dens of the axis at the atlantoaxial joints (the no joint). Strong ligaments, especially the transverse and alar ligaments, keep the dens from pressing on the spinal cord. Damage to them can be life-threatening.",
  flow:["Atlanto-occipital: condyles on atlas lateral masses, ellipsoid synovial","Allows flexion-extension (nodding) and slight side flexion","Median atlantoaxial: pivot joint, dens in osseoligamentous ring","Lateral atlantoaxial: plane joints between facets","Atlantoaxial allows about half of neck rotation","Ligament laxity risks cord compression; screen before manual therapy"],
  exam:[
    {h:"Atlanto-occipital joints", p:["Type: paired synovial ellipsoid (condylar) joints between convex occipital condyles and concave superior facets of the atlas lateral masses.","Ligaments: fibrous capsule, anterior atlanto-occipital membrane (continuation of ALL), posterior atlanto-occipital membrane (pierced by the vertebral artery and C1 nerve).","Movements: flexion and extension (nodding, about 15-25 degrees total), slight lateral flexion; little or no rotation."]},
    {h:"Atlantoaxial joints", p:["Median atlantoaxial: synovial pivot joint between the dens and a ring formed by the anterior arch of the atlas in front and the transverse ligament behind; two synovial cavities (front and back of dens).","Lateral atlantoaxial (two): synovial plane joints between inferior facets of the atlas and superior facets of the axis.","Movement: rotation of the atlas and skull around the dens, about 40-45 degrees each side, roughly half of total cervical rotation."]},
    {h:"Ligaments connecting axis and occiput", p:["Cruciform ligament: transverse ligament of atlas plus superior and inferior longitudinal bands to the occiput and body of axis.","Alar ligaments: from sides of the dens to the medial sides of the occipital condyles; check excessive rotation and side flexion.","Apical ligament of dens to anterior margin of foramen magnum; tectorial membrane, the upward continuation of the PLL, from the body of axis to the basiocciput, covering the other ligaments."]},
    {h:"Muscles producing movements", p:["Flexion: longus capitis, rectus capitis anterior (C1-C2 ventral rami), with SCM.","Extension: rectus capitis posterior major and minor, obliquus capitis superior, semispinalis capitis, splenius capitis (suboccipital muscles by the suboccipital nerve, dorsal ramus of C1).","Rotation: obliquus capitis inferior, rectus capitis posterior major, splenius capitis (same side), opposite SCM."]},
    {h:"Blood and nerve supply", p:["Arteries: vertebral artery branches and ascending pharyngeal artery; nerves: C1 and C2 rami.","Suboccipital triangle (rectus capitis posterior major, obliquus capitis superior and inferior) contains the vertebral artery and suboccipital nerve; greater occipital nerve crosses its roof."]},
    {h:"Applied anatomy and physiotherapy relevance", p:["Rupture or laxity of the transverse ligament (trauma, rheumatoid arthritis, Down syndrome) allows the dens to slide back and compress the cord; atlantodental interval above about 3 mm in adults is abnormal.","Before cervical manual therapy, screen for upper cervical instability and vascular insufficiency (IFOMPT framework); test with Sharp-Purser and alar ligament stress tests only with training.","Cervicogenic headache arises from C1-C3 structures; physiotherapy uses deep neck flexor training, upper cervical mobilisation and posture work.","The flexion-rotation test isolates C1-C2 rotation and is reduced in cervicogenic headache."]},
    {h:"Conclusion", p:["The craniovertebral joints give the head its yes and no movements, but depend on small strong ligaments that must be respected in assessment and treatment."]}
  ],
  tip:"Draw a superior view of the atlas with the dens and transverse ligament (cruciform), and a posterior view after removing arches showing alar, apical ligaments and tectorial membrane.",
  evidence:[["Deep neck flexor training for cervicogenic headache","Reduces headache frequency and intensity","Moderate"],["Upper cervical mobilisation for cervicogenic headache","Short-term benefit, best combined with exercise","Low-moderate"],["Clinical ligament stress tests for upper cervical instability","Limited diagnostic accuracy; imaging needed when suspected","Low"]],
  evidenceSource:"Jull et al. Spine 2002 (exercise and manipulative therapy for cervicogenic headache); IFOMPT International framework for examination of the cervical region (Rushton et al. 2020)",
  outcomes:[["Flexion-rotation test","C1-C2 rotation range"],["Craniocervical flexion test","Deep neck flexor endurance"],["Headache diary","Frequency and intensity"]],
  recent:["The IFOMPT cervical framework (2020) guides clinical reasoning about vascular and instability risks before neck manual therapy."],
  mnemonic:{word:"Yes on top, No below", items:[["Yes","Atlanto-occipital: nodding"],["No","Atlantoaxial: rotation"],["TAAT","Transverse, Alar, Apical, Tectorial"]], extra:"Transverse ligament is the key restraint of the dens."},
  example:"A 12-year-old boy with Down syndrome from Kolkata wants to join a gymnastics class; his doctor advises screening for atlantoaxial instability before he does forward rolls.",
  flags:["Lip or tongue tingling, drop attacks or bilateral limb signs on neck movement","Neck pain after major trauma (cervical spine clearance first)","Rheumatoid arthritis with new neck pain and limb weakness"],
  viva:[["Type of median atlantoaxial joint?","Synovial pivot joint."],["What does the tectorial membrane continue from?","The posterior longitudinal ligament."],["Which movement occurs mainly at the atlanto-occipital joint?","Flexion and extension (nodding)."]],
  refs:[{c:"Chaurasia BD. Human Anatomy, Volume 3: Head and Neck. Chapter: Joints of the head and neck."},{b:"levangie",ch:"The vertebral column"},{b:"maitlandV",ch:"Upper cervical spine"}],
  keywords:"atlanto-occipital atlantoaxial joint transverse alar ligament craniovertebral",
  mcq:[["The alar ligaments connect the dens to the:",["Anterior arch of atlas","Occipital condyles","Body of C3","Posterior arch of atlas"],1,"They run from the sides of the dens to the medial sides of the occipital condyles."],["Rotation of the head mainly occurs at the:",["Atlanto-occipital joint","Atlantoaxial joints","C5-C6 joint","Uncovertebral joints"],1,"About half of cervical rotation occurs at C1-C2."]]
},
{
  id:"ah-neck-arteries-circle-willis", title:"Subclavian, vertebral and carotid arteries; circle of Willis", subject:"Anatomy", region:"Head and neck",
  stages:"steps",
  aliases:["subclavian artery","vertebral artery","common carotid artery","internal carotid artery","circle of Willis","arterial circle of brain","basilar artery"],
  simple:"The brain, head, neck and arms get blood from three main arteries in the neck: the subclavian, the carotids and the vertebrals, which come off the subclavian. At the base of the brain the carotids and vertebrals join into a ring called the circle of Willis. This ring lets blood reach the brain by another route when one vessel narrows slowly.",
  flow:["Right subclavian and right common carotid from brachiocephalic trunk","Left ones arise directly from arch of aorta","Subclavian: three parts around scalenus anterior","Vertebral: through C6-C1 transverse foramina into skull","Carotid divides at C3-C4 into internal and external","Circle of Willis: anastomosis linking both carotids and basilar"],
  exam:[
    {h:"Subclavian artery", p:["Origin: right from the brachiocephalic trunk, left from the arch of aorta; scalenus anterior divides it into three parts; continues as axillary artery at the outer border of the first rib.","First part branches: vertebral, internal thoracic, thyrocervical trunk (inferior thyroid, suprascapular, transverse cervical); second part: costocervical trunk (superior intercostal and deep cervical arteries); third part: often the dorsal scapular artery.","Lies on the first rib with the lower trunk of the brachial plexus behind it in the scalene triangle."]},
    {h:"Vertebral artery", p:["First part from subclavian to C6 transverse foramen; second part through foramina C6 to C1; third part winds behind the lateral mass of atlas in the suboccipital triangle; fourth part pierces dura and passes through foramen magnum.","The two vertebrals join at the lower border of the pons to form the basilar artery, which gives pontine, labyrinthine, superior cerebellar and posterior cerebral arteries.","Branches of vertebral: anterior and posterior spinal arteries, posterior inferior cerebellar artery (PICA), meningeal branches."]},
    {h:"Carotid arteries", p:["Common carotid: right from brachiocephalic trunk, left from arch; runs in the carotid sheath with IJV lateral and vagus behind; bifurcates at the upper border of thyroid cartilage (C3-C4).","External carotid: supplies face, scalp and neck; branches superior thyroid, lingual, facial, ascending pharyngeal, occipital, posterior auricular, maxillary and superficial temporal.","Internal carotid: no branches in the neck; enters carotid canal, passes through cavernous sinus, gives ophthalmic, posterior communicating, anterior choroidal, then anterior and middle cerebral arteries."]},
    {h:"Circle of Willis", p:["Located in the interpeduncular fossa at the base of the brain around the optic chiasma and pituitary stalk.","Formed by: anterior communicating artery, two anterior cerebral arteries, two internal carotids, two posterior communicating arteries and two posterior cerebral arteries (from basilar).","Function: anastomosis equalising flow between the carotid and vertebrobasilar systems; often incomplete or variable in many people."]},
    {h:"Territories of cerebral arteries", p:["Anterior cerebral: medial surface of the hemisphere including leg and foot motor-sensory area.","Middle cerebral: most of the lateral surface including face and arm areas, Broca and Wernicke areas in the dominant hemisphere; lenticulostriate branches to internal capsule.","Posterior cerebral: occipital lobe (vision), inferior temporal lobe and thalamus."]},
    {h:"Applied anatomy and physiotherapy relevance", p:["MCA stroke: contralateral hemiplegia worse in face and arm, sensory loss, aphasia if dominant side; ACA stroke: contralateral leg weakness; PCA: homonymous hemianopia.","Berry aneurysms at circle junctions (commonly anterior communicating) rupture causing subarachnoid haemorrhage.","Subclavian steal syndrome: proximal subclavian block causes reversed vertebral flow and dizziness on arm exercise; thoracic outlet compression of the subclavian artery gives arm ischaemia.","Vertebral artery dissection can mimic neck pain and headache; screen for dizziness, diplopia, dysarthria, dysphagia, drop attacks, nystagmus, numbness before neck manual therapy."]},
    {h:"Conclusion", p:["Knowing the neck arteries and circle of Willis lets the physiotherapist predict stroke patterns and practise safe neck treatment."]}
  ],
  tip:"Draw the circle of Willis as a heptagon on the brain base with all named vessels, and beside it a front view of the aortic arch giving brachiocephalic, left carotid and left subclavian arteries.",
  evidence:[["Organised stroke unit care","Reduces death and dependency after stroke","High"],["Task-specific training after stroke","Improves functional mobility","Moderate"],["Pre-manipulation vertebral artery provocation tests","Poor diagnostic accuracy; clinical reasoning preferred","Low"]],
  evidenceSource:"Cochrane review of organised inpatient stroke unit care; IFOMPT cervical framework (Rushton et al. 2020)",
  outcomes:[["NIH Stroke Scale","Stroke severity"],["Fugl-Meyer Assessment","Motor recovery after stroke"],["Doppler or CT angiography","Vessel narrowing or dissection"]],
  recent:["Mechanical thrombectomy for large-vessel anterior circulation stroke is now standard care in eligible patients within extended time windows."],
  mnemonic:{word:"VIT C, D", items:[["V","Vertebral"],["I","Internal thoracic"],["T","Thyrocervical trunk"],["C","Costocervical trunk"],["D","Dorsal scapular"]], extra:"Branches of subclavian artery in order."},
  example:"A 62-year-old diabetic man from Nagpur suddenly develops weakness of his right face and arm more than leg, with difficulty finding words: a left middle cerebral artery stroke.",
  flags:["Sudden severe headache (thunderclap; subarachnoid haemorrhage)","Neck pain with dizziness, double vision or slurred speech (vertebral dissection)","Arm pain, pallor and cold hand on exercise (arterial thoracic outlet)"],
  viva:[["Name the branches of the internal carotid in the neck.","None; it gives no branches in the neck."],["Where does the basilar artery form?","At the lower border of the pons from the two vertebral arteries."],["Which artery supplies the leg area of motor cortex?","Anterior cerebral artery."]],
  refs:[{c:"Chaurasia BD. Human Anatomy, Volume 3: Head and Neck. Chapters: Root of the neck; Blood supply of brain."},{b:"inderbir",ch:"Blood supply of the brain"},{b:"osullivan",ch:"Stroke"}],
  keywords:"subclavian vertebral carotid artery circle of Willis cerebral arteries stroke",
  mcq:[["Which artery is NOT part of the circle of Willis?",["Anterior communicating","Posterior communicating","Middle cerebral","Posterior cerebral"],2,"The middle cerebral is a terminal branch of the internal carotid but not part of the ring."],["The vertebral artery normally enters the foramen transversarium of:",["C7","C6","C4","C1"],1,"It enters at C6 and ascends through C6-C1."]]
},
{
  id:"ah-brain-parts-ans", title:"Parts of the brain and their functions; autonomic nervous system", subject:"Anatomy", region:"Head and neck",
  stages:"steps",
  aliases:["parts of brain","cerebrum lobes","cerebellum functions","brainstem","autonomic nervous system","sympathetic and parasympathetic","basal ganglia"],
  simple:"The brain has the cerebrum for thinking, movement and sensation, the cerebellum for coordination and balance, and the brainstem that controls breathing, heart rate and carries pathways to the spinal cord. Deep centres such as the basal ganglia and thalamus fine-tune movement and relay sensation. The autonomic nervous system controls organs automatically through sympathetic (fight or flight) and parasympathetic (rest and digest) divisions.",
  flow:["Forebrain: cerebrum and diencephalon","Midbrain, pons and medulla form brainstem","Cerebellum coordinates movement, posture and balance","Lobes have localised functions (motor, sensory, vision, hearing)","ANS: sympathetic T1-L2, parasympathetic cranial and S2-S4","Lesion site predicts signs and guides neuro rehab"],
  exam:[
    {h:"Divisions of the brain", p:["Forebrain (prosencephalon): telencephalon (cerebral hemispheres, basal ganglia) and diencephalon (thalamus, hypothalamus, epithalamus, subthalamus).","Midbrain (mesencephalon) and hindbrain (rhombencephalon: pons, medulla, cerebellum); midbrain, pons and medulla form the brainstem.","Coverings: dura, arachnoid, pia; CSF formed by choroid plexuses in the ventricles circulates to the subarachnoid space."]},
    {h:"Cerebrum: lobes and functional areas", p:["Frontal: primary motor area (precentral gyrus, area 4) with inverted body map (homunculus), premotor (area 6), frontal eye field (8), Broca motor speech area (44, 45, dominant side), prefrontal cortex for personality, judgement and planning.","Parietal: primary somatosensory (postcentral gyrus, areas 3, 1, 2), association areas for body image and spatial awareness (lesion of non-dominant side causes neglect).","Temporal: primary auditory (41, 42), Wernicke area (22, understanding speech), memory with hippocampus; occipital: primary visual cortex (17) around the calcarine sulcus.","White matter: internal capsule carries corticospinal and thalamocortical fibres; corpus callosum joins the two hemispheres."]},
    {h:"Deep nuclei and diencephalon", p:["Basal ganglia (caudate, putamen, globus pallidus, with subthalamic nucleus and substantia nigra) plan and scale movement; lesions cause Parkinsonism, chorea or hemiballismus.","Thalamus: relay station for all sensations except smell to the cortex; hypothalamus controls temperature, hunger, thirst, endocrine (pituitary) and autonomic function."]},
    {h:"Brainstem and cerebellum", p:["Midbrain: nuclei of III and IV, substantia nigra, red nucleus, cerebral peduncles; pons: nuclei of V-VIII, pontine nuclei relaying to cerebellum; medulla: IX-XII, cardiac, vasomotor and respiratory centres, pyramidal decussation.","Brainstem carries ascending and descending tracts and the reticular formation for arousal.","Cerebellum: connected by three peduncles; vestibulocerebellum (balance, eye movement), spinocerebellum (tone, posture, limb coordination), cerebrocerebellum (planning skilled movement); lesions give ipsilateral ataxia, intention tremor, dysmetria, dysdiadochokinesia, nystagmus and hypotonia."]},
    {h:"Autonomic nervous system", p:["Two-neuron chain: preganglionic from CNS to ganglion, postganglionic to the organ.","Sympathetic (thoracolumbar, T1-L2 lateral horn): short preganglionic fibres to the sympathetic chain or prevertebral ganglia, long postganglionic noradrenergic fibres; increases heart rate, BP, bronchodilation, pupil dilation, sweating, glycogen breakdown, relaxes bladder wall; adrenal medulla receives preganglionic fibres directly.","Parasympathetic (craniosacral: III, VII, IX, X and S2-S4): long preganglionic fibres, ganglia near the organ, acetylcholine at both synapses; slows the heart, constricts pupils and bronchi, increases gut motility and secretion, contracts the bladder detrusor.","Higher control by hypothalamus and brainstem centres."]},
    {h:"Applied anatomy and physiotherapy relevance", p:["Cortical and internal capsule stroke: contralateral hemiplegia; cerebellar lesions: ipsilateral ataxia treated with Frenkel exercises, balance training and weights; basal ganglia disease (Parkinson): cueing, big amplitude and gait training.","Brainstem lesions cause crossed signs (ipsilateral cranial nerve, contralateral limbs).","Autonomic dysreflexia in spinal cord injury above T6: sudden high BP, headache and bradycardia from a noxious stimulus below the lesion; sit up, remove the cause (often full bladder) and get help.","Orthostatic hypotension after SCI or prolonged bed rest: tilt table, abdominal binder and graded positioning; Horner syndrome (ptosis, miosis, anhidrosis) from cervical sympathetic damage."]},
    {h:"Conclusion", p:["Knowing which part of the brain does what, and how the ANS controls organs, lets the physiotherapist localise lesions, predict problems and plan safe neuro rehabilitation."]}
  ],
  tip:"Draw a lateral view of the cerebral hemisphere with lobes and numbered key areas (4, 3-1-2, 44-45, 22, 17, 41-42) plus a small sagittal sketch showing brainstem and cerebellum; add a two-column table comparing sympathetic and parasympathetic.",
  evidence:[["Task-specific and intensive rehabilitation after stroke","Improves motor function and independence","Moderate-high"],["Balance and coordination training in cerebellar ataxia","May improve balance and gait","Low-moderate"],["External cueing and amplitude training in Parkinson disease","Improves gait speed and stride length","Moderate"]],
  evidenceSource:"Inderbir Singh neuroanatomy; Cochrane reviews of stroke rehabilitation and physiotherapy in Parkinson disease",
  outcomes:[["Glasgow Coma Scale","Level of consciousness"],["Scale for Assessment and Rating of Ataxia (SARA)","Cerebellar ataxia severity"],["Heart rate and BP response to tilt","Autonomic function"]],
  recent:["Brain imaging research highlights neuroplasticity, supporting high-repetition task practice after brain injury."],
  mnemonic:{word:"DANISH", items:[["D","Dysdiadochokinesia"],["A","Ataxia"],["N","Nystagmus"],["I","Intention tremor"],["S","Slurred (scanning) speech"],["H","Hypotonia"]], extra:"Cerebellar signs are on the same side as the lesion."},
  example:"A 34-year-old man in Ahmedabad with T4 paraplegia suddenly gets a pounding headache, sweating above the injury and BP of 190/110 during a physio session; his catheter is blocked: autonomic dysreflexia.",
  flags:["Sudden severe headache with high BP in SCI above T6 (autonomic dysreflexia)","Sudden facial or limb weakness, speech loss (stroke, call emergency)","Falling GCS or new pupil asymmetry (raised intracranial pressure)"],
  viva:[["Where is Broca area?","Inferior frontal gyrus of the dominant hemisphere, areas 44 and 45."],["Outflow of sympathetic system?","Lateral horn of T1-L2 segments (thoracolumbar)."],["Side of signs in a cerebellar lesion?","Same side as the lesion."]],
  refs:[{b:"inderbir",ch:"Cerebral hemispheres; cerebellum; autonomic nervous system"},{c:"Chaurasia BD. Human Anatomy, Volume 4: Brain-Neuroanatomy. Chapters: Cerebrum; Autonomic nervous system."},{b:"umphred",ch:"Movement analysis across the lifespan and neurological disorders"}],
  keywords:"brain parts functions cerebrum cerebellum brainstem autonomic sympathetic parasympathetic",
  mcq:[["The primary visual cortex is area:",["4","17","22","44"],1,"Area 17 lies around the calcarine sulcus of the occipital lobe."],["Parasympathetic outflow arises from:",["T1-L2","C5-T1","Cranial nerves III, VII, IX, X and S2-S4","L1-L3 only"],2,"Parasympathetic is craniosacral."]]
},
{
  id:"ah-eye-nose-ear-tmj", title:"Eye, nose and ear; temporomandibular joint", subject:"Anatomy", region:"Head and neck",
  stages:"steps",
  aliases:["temporomandibular joint","TMJ","extraocular muscles","middle ear","vestibular apparatus","nasal cavity","muscles of mastication"],
  simple:"The eye is moved by six small muscles supplied by three cranial nerves. The ear has outer, middle and inner parts; the inner ear holds the cochlea for hearing and the vestibular organs for balance. The nose warms and filters air and carries smell. The temporomandibular joint lets the jaw open, close and chew, and physiotherapists often treat its pain and clicking.",
  flow:["Eye: 6 extraocular muscles (LR6, SO4, rest III)","Nose: conchae, meatuses, sinuses; olfaction via I","Ear: external, middle (ossicles), internal (cochlea, vestibule)","TMJ: synovial joint with articular disc, two compartments","Opening: hinge then glide forward; muscles of mastication by V3","Vertigo, TMJ dysfunction and dislocation are applied points"],
  exam:[
    {h:"Eye (outline)", p:["Eyeball has three coats: outer fibrous (sclera, cornea), middle vascular (choroid, ciliary body, iris), inner retina; lens, aqueous and vitreous humour.","Extraocular muscles: four recti and two obliques plus levator palpebrae superioris; lateral rectus by VI, superior oblique by IV, all others by III.","Actions in clinical testing: superior oblique looks down when the eye is adducted; inferior oblique up in adduction; superior rectus up in abduction; inferior rectus down in abduction.","Visual pathway: retina, optic nerve, chiasma (nasal fibres cross), optic tract, lateral geniculate body, optic radiation, area 17."]},
    {h:"Nose and ear (outline)", p:["Nasal cavity: septum (ethmoid, vomer, cartilage), lateral wall with superior, middle and inferior conchae; paranasal sinuses drain into meatuses (frontal, maxillary, anterior ethmoid into middle meatus; nasolacrimal duct into inferior); olfactory area in the roof.","External ear: auricle and external acoustic meatus; middle ear: tympanic membrane, malleus, incus, stapes, tensor tympani (V3) and stapedius (VII), auditory tube to nasopharynx.","Internal ear: cochlea (hearing, organ of Corti), vestibule (utricle and saccule for linear acceleration and head tilt) and three semicircular canals (angular acceleration), supplied by VIII."]},
    {h:"Temporomandibular joint: type and articular surfaces", p:["Type: synovial, bicondylar (condylar) joint; compound because an articular disc divides it; surfaces covered by fibrocartilage, not hyaline cartilage.","Upper surface: articular eminence and mandibular (glenoid) fossa of the temporal bone; lower: head of the mandible.","Articular disc divides the cavity into upper (gliding, translation) and lower (hinge, rotation) compartments; lateral pterygoid inserts partly into the disc and capsule."]},
    {h:"Ligaments, nerve and blood supply", p:["Lateral (temporomandibular) ligament strengthens the capsule; accessory sphenomandibular and stylomandibular ligaments.","Nerve supply: auriculotemporal and masseteric branches of mandibular nerve (Hilton law); blood supply from superficial temporal and maxillary arteries."]},
    {h:"Movements and muscles", p:["Opening (depression): early rotation in lower compartment, then forward translation of head and disc onto the eminence; lateral pterygoids with digastric, geniohyoid and mylohyoid, plus gravity.","Closing (elevation): temporalis, masseter, medial pterygoid.","Protrusion: lateral and medial pterygoids of both sides; retraction: posterior fibres of temporalis and deep masseter.","Side-to-side grinding: medial and lateral pterygoids of one side acting alternately with the opposite side's temporalis; normal mouth opening is about 35-50 mm (about three fingers)."]},
    {h:"Applied anatomy and physiotherapy relevance", p:["TMJ dysfunction (temporomandibular disorders): pain, clicking (anterior disc displacement with reduction), limited opening, linked to bruxism, stress and posture; physiotherapy uses education, jaw exercises (controlled opening, tongue-up position), soft tissue work, posture correction and joint mobilisation.","Anterior dislocation occurs on wide yawning when the head slips in front of the eminence; reduced by pressing the molars down and back.","Benign paroxysmal positional vertigo from otoconia in the posterior semicircular canal: Dix-Hallpike test and Epley repositioning manoeuvre; vestibular rehab for unilateral hypofunction.","Eye movement palsies and diplopia are assessed in stroke and head injury; hearing loss affects communication during therapy."]},
    {h:"Conclusion", p:["The special sense organs and the TMJ are small but clinically important, especially for vertigo, jaw pain and cranial nerve assessment in physiotherapy."]}
  ],
  tip:"Draw a sagittal section of the TMJ in closed and open mouth positions showing disc, eminence and lateral pterygoid, plus a small sketch of the eye with muscles labelled LR6 SO4.",
  evidence:[["Epley manoeuvre for posterior canal BPPV","Resolves vertigo in most patients compared with sham","High"],["Exercise and manual therapy for TMD","Reduce pain and improve mouth opening","Moderate"],["Vestibular rehabilitation for unilateral vestibular hypofunction","Improves dizziness and balance","Moderate-high"]],
  evidenceSource:"Cochrane reviews of Epley manoeuvre and vestibular rehabilitation; systematic reviews of exercise therapy for temporomandibular disorders",
  outcomes:[["Maximal mouth opening in mm","TMJ mobility"],["Dizziness Handicap Inventory","Impact of vertigo"],["Dix-Hallpike test","Posterior canal BPPV"]],
  recent:["The Diagnostic Criteria for Temporomandibular Disorders (DC/TMD, 2014) is the standard research and clinical classification."],
  mnemonic:{word:"LR6 SO4, rest 3", items:[["LR6","Lateral rectus by abducent (VI)"],["SO4","Superior oblique by trochlear (IV)"],["3","Others by oculomotor (III)"]], extra:"TMJ: rotate then glide on opening."},
  example:"A 26-year-old software engineer in Hyderabad has right jaw pain and clicking on opening, worse during exam deadlines when she grinds her teeth at night: TMJ disc displacement with reduction.",
  flags:["Jaw pain with exertion or sweating (possible cardiac referral)","Sudden hearing loss or vertigo with neurological signs (stroke, urgent)","Jaw claudication with headache in an older adult (giant cell arteritis)"],
  viva:[["Which muscle opens the mouth and protrudes the jaw?","Lateral pterygoid."],["Why is the TMJ covered by fibrocartilage?","It develops from membrane (intramembranous bones), so its surfaces are fibrocartilage."],["Nerve supply of lateral rectus?","Abducent nerve (VI)."]],
  refs:[{c:"Chaurasia BD. Human Anatomy, Volume 3: Head and Neck. Chapters: Temporal and infratemporal regions; Orbit; Ear; Nose."},{b:"magee",ch:"Temporomandibular joint"},{b:"umphred",ch:"Vestibular disorders"}],
  keywords:"eye nose ear temporomandibular joint TMJ mastication vertigo",
  mcq:[["The TMJ articular surfaces are covered by:",["Hyaline cartilage","Fibrocartilage","Elastic cartilage","Bone only"],1,"The TMJ, like the sternoclavicular joint, has fibrocartilage-covered surfaces."],["Superior oblique muscle is supplied by:",["Oculomotor","Abducent","Trochlear","Ophthalmic"],2,"SO4: trochlear nerve."]]
},
{
  id:"ah-bony-pelvis-sex-differences", title:"Bony pelvis: male and female features", subject:"Anatomy", region:"Pelvis",
  stages:"steps",
  aliases:["bony pelvis","sex differences of pelvis","male and female pelvis","pelvic inlet","pelvic outlet","gynaecoid pelvis","greater and lesser pelvis"],
  simple:"The bony pelvis is a ring made of the two hip bones, the sacrum and the coccyx. It carries body weight from the spine to the legs and protects pelvic organs. The female pelvis is wider, shallower and rounder to allow childbirth, while the male pelvis is heavier, narrower and deeper.",
  flow:["Ring: two hip bones, sacrum, coccyx","Pelvic brim divides greater (false) and lesser (true) pelvis","Inlet, cavity and outlet have defined diameters","Female: wide round inlet, wide subpubic angle, shallow cavity","Male: heart-shaped inlet, narrow angle, deep heavy pelvis","Fractures, obstetric diameters and posture link to physio"],
  exam:[
    {h:"Introduction and parts", p:["Formed by two hip bones (ilium, ischium, pubis fused at the acetabulum), sacrum and coccyx, joined by two sacroiliac joints, the pubic symphysis and the sacrococcygeal joint.","Pelvic brim (sacral promontory, alae, arcuate and pectineal lines, pubic crest and upper symphysis) divides the greater (false) pelvis above from the lesser (true) pelvis below.","Functions: transmits weight from the vertebral column to the femora in standing and to the ischial tuberosities in sitting; protects pelvic viscera; attachment for trunk and limb muscles; birth canal in females."]},
    {h:"Inlet, cavity and outlet", p:["Inlet: bounded by the brim; diameters are anteroposterior (true conjugate, about 11 cm), transverse (about 13 cm) and oblique (about 12 cm) in the female.","Cavity: short curved canal, deeper behind than in front; ischial spines project into it and are a landmark for descent of the fetal head and for pudendal block.","Outlet: diamond-shaped, bounded by the lower symphysis, ischiopubic rami, ischial tuberosities, sacrotuberous ligaments and coccyx tip; AP diameter increases as the coccyx moves back in labour."]},
    {h:"Sex differences", p:["General: male bones are heavier and rougher with stronger muscle markings; female pelvis is light and smooth.","Greater pelvis wider and shallower in the female; true pelvis wide and shallow (cylindrical) in the female, narrow and deep (funnel-shaped) in the male.","Inlet: round or oval in the female (gynaecoid), heart-shaped in the male (promontory projects more); subpubic angle about 80-85 degrees in female (angle between thumb and index), about 50-60 degrees in male (between index and middle fingers).","Female: wider greater sciatic notch (nearly 90 degrees), everted ischial tuberosities and spines further apart, smaller acetabulum (diameter about equal to distance from its edge to symphysis), oval obturator foramen, broad short less-curved sacrum and preauricular sulcus often present; male: narrow notch, larger acetabulum, round obturator foramen, long narrow curved sacrum."]},
    {h:"Pelvic types (Caldwell-Moloy)", p:["Gynaecoid (round inlet, the typical female type), android (heart-shaped, male type), anthropoid (long AP diameter) and platypelloid (flat, wide transverse diameter).","Pelvic shape matters for the mechanism of labour and is relevant in medicolegal identification of sex from skeletal remains."]},
    {h:"Applied anatomy and physiotherapy relevance", p:["Pelvic ring fractures (often from road traffic accidents) can damage the bladder, urethra and pelvic vessels; stable fractures are mobilised with protected weight bearing as advised.","Avulsion fractures at the ASIS (sartorius), AIIS (rectus femoris) and ischial tuberosity (hamstrings) occur in adolescent sprinters and footballers; treated with rest then graded strengthening.","A wider female pelvis increases the Q angle at the knee, relevant in patellofemoral pain; pelvic tilt and obliquity are checked in posture and gait assessment.","Antenatal and postnatal physiotherapy addresses pelvic girdle pain, posture and pelvic floor training."]},
    {h:"Conclusion", p:["The bony pelvis is a weight-bearing ring whose sex differences reflect childbirth, and its landmarks are used daily in physiotherapy assessment."]}
  ],
  tip:"Draw male and female pelvises side by side from the front, showing inlet shape (heart vs oval) and subpubic angle (narrow vs wide), and list differences in a two-column table.",
  evidence:[["Exercise during pregnancy","Safe for uncomplicated pregnancy and reduces some complications","Moderate-high"],["Graded rehabilitation after pelvic avulsion fracture","Most athletes return to sport with conservative care","Low"]],
  evidenceSource:"B D Chaurasia; ACOG committee opinion on physical activity in pregnancy; WHO 2020 physical activity guidelines",
  outcomes:[["Pelvic tilt and obliquity observation","Alignment in posture"],["Q angle","Effect of pelvic width on knee"],["Timed Up and Go after pelvic fracture","Functional mobility"]],
  recent:["The WHO 2020 physical activity guidelines recommend at least 150 minutes of moderate activity weekly for pregnant and postpartum women without contraindications."],
  mnemonic:{word:"Female pelvis is WIDER", items:[["W","Wide subpubic angle"],["I","Inlet round or oval"],["D","Diameter of cavity greater, shallow"],["E","Everted ischial tuberosities"],["R","Round smooth light bones, short broad sacrum"]], extra:"Male: heavy, deep, narrow, heart-shaped inlet."},
  example:"A 15-year-old sprinter from Thrissur feels a pop at the front of his hip while starting a 100 m race; X-ray shows an avulsion of the anterior superior iliac spine by sartorius.",
  flags:["Pelvic fracture with blood at urethral meatus (urethral injury, do not catheterise)","Hypotension after pelvic trauma (major bleeding)","Pelvic or groin pain with weight loss or night pain (tumour or infection)"],
  viva:[["Which bones form the pelvis?","Two hip bones, sacrum and coccyx."],["Subpubic angle in females?","About 80-85 degrees."],["Name the four pelvic types.","Gynaecoid, android, anthropoid, platypelloid."]],
  refs:[{c:"Chaurasia BD. Human Anatomy, Volume 2: Lower Limb, Abdomen and Pelvis. Chapter: Osteology of pelvis; sex differences."},{b:"levangie",ch:"The hip complex"},{b:"neumann",ch:"Hip"}],
  keywords:"bony pelvis male female differences inlet outlet gynaecoid",
  mcq:[["The subpubic angle in a typical female pelvis is about:",["50-60 degrees","80-85 degrees","100-110 degrees","120 degrees"],1,"Female subpubic angle is wide, about 80-85 degrees."],["Which pelvic inlet shape is typical of the male?",["Round","Oval transversely","Heart-shaped","Long anteroposteriorly"],2,"The android pelvis has a heart-shaped inlet."]]
},
{
  id:"ah-pelvic-joints-sij", title:"Pelvic joints: pubic symphysis and sacroiliac joint", subject:"Anatomy", region:"Pelvis",
  stages:"steps",
  aliases:["sacroiliac joint","SI joint","pubic symphysis","nutation","counternutation","sacrotuberous ligament","pelvic girdle pain"],
  simple:"The pelvic ring has two strong sacroiliac joints at the back where the sacrum meets the ilia, and the pubic symphysis in front. These joints move only a few degrees but transfer the whole weight of the upper body to the legs. They are held by some of the strongest ligaments in the body, and in pregnancy they loosen and can become painful.",
  flow:["Sacroiliac: synovial in front, fibrous behind; very strong ligaments","Pubic symphysis: secondary cartilaginous joint with fibrocartilage disc","Sacrococcygeal and lumbosacral joints complete the ring","Movement: small nutation and counternutation","Form and force closure stabilise the joints","SIJ pain, symphysis dysfunction in pregnancy and sacroiliitis"],
  exam:[
    {h:"Sacroiliac joint: type and surfaces", p:["Type: synovial plane joint anteriorly (auricular surfaces) combined with a syndesmosis posteriorly (interosseous ligament); becomes increasingly fibrous with age.","Surfaces: auricular surface of sacrum (S1-S3) covered by hyaline cartilage, ilium by thinner fibrocartilage; irregular ridges and depressions interlock (form closure).","The sacrum is wedged between the ilia, wider in front and above, so body weight drives it into the joint."]},
    {h:"Ligaments of the sacroiliac joint", p:["Interosseous sacroiliac ligament: strongest, fills the space behind the joint surfaces.","Anterior sacroiliac ligament (thin) and posterior sacroiliac ligaments (short and long; long posterior ligament palpable below the PSIS).","Accessory: sacrotuberous and sacrospinous ligaments (resist upward tilt of the lower sacrum and convert sciatic notches into greater and lesser sciatic foramina) and iliolumbar ligament (L5 transverse process to iliac crest)."]},
    {h:"Movements and stability", p:["Nutation: sacral promontory moves forward and down, coccyx back; occurs in standing and lumbar extension, increases outlet diameter; resisted by sacrotuberous, sacrospinous and interosseous ligaments.","Counternutation: promontory moves back; increases inlet diameter; resisted by the long posterior sacroiliac ligament.","Range is only about 1-4 degrees of rotation with 1-2 mm translation.","Force closure by gluteus maximus, latissimus dorsi through thoracolumbar fascia, biceps femoris via sacrotuberous ligament, multifidus, transversus abdominis and pelvic floor."]},
    {h:"Nerve and blood supply", p:["Nerve: dorsal rami of L5-S3 (lateral branches) posteriorly and ventral rami of L4-S2 or branches of the obturator and superior gluteal nerves anteriorly; pain may refer to buttock, groin and posterior thigh.","Arteries: iliolumbar, superior gluteal and lateral sacral arteries."]},
    {h:"Pubic symphysis and other joints", p:["Pubic symphysis: secondary cartilaginous joint between the pubic bodies, each lined by hyaline cartilage, joined by a fibrocartilaginous disc that may show a cavity; superior pubic and inferior (arcuate) pubic ligaments strengthen it.","Allows slight separation and shear; widens a few mm in pregnancy under hormonal influence.","Lumbosacral joint (L5-S1 disc and facets, iliolumbar ligament) and sacrococcygeal joint (symphysis) complete the pelvic linkage."]},
    {h:"Applied anatomy and physiotherapy relevance", p:["Pregnancy-related pelvic girdle pain and symphysis pubis dysfunction: pain on walking, stairs and turning in bed; managed with education, pelvic belt, stabilisation exercise and activity modification.","Sacroiliitis is an early sign of ankylosing spondylitis (inflammatory back pain, morning stiffness under 45-60 minutes improving with exercise).","SIJ pain is diagnosed by a cluster of provocation tests (distraction, thigh thrust, compression, sacral thrust, Gaenslen); three or more positive suggests SIJ pain.","Active straight leg raise test assesses load transfer through the pelvis; treatment includes motor control, gluteal and core strengthening and manual therapy."]},
    {h:"Conclusion", p:["The pelvic joints move little but carry large loads; their ligaments and muscles explain pelvic girdle pain and its physiotherapy management."]}
  ],
  tip:"Draw a posterior view of the pelvis showing the SIJ with interosseous, posterior sacroiliac, sacrotuberous and sacrospinous ligaments, and a side view arrow diagram of nutation and counternutation.",
  evidence:[["Cluster of SIJ provocation tests (Laslett)","Three or more of five positive improves diagnostic accuracy","Moderate"],["Exercise for pregnancy-related pelvic girdle pain","May reduce pain and sick leave","Low-moderate"],["Pelvic belt in pelvic girdle pain","Short-term symptom relief for some women","Low"]],
  evidenceSource:"Laslett et al. Manual Therapy 2005; European guidelines for pelvic girdle pain (Vleeming et al. 2008); Cochrane review of interventions for pelvic and back pain in pregnancy",
  outcomes:[["Pelvic Girdle Questionnaire","Activity limitation in pelvic girdle pain"],["Active straight leg raise test","Load transfer through pelvis"],["SIJ provocation test cluster","Likelihood of SIJ pain"]],
  recent:["European guidelines on pelvic girdle pain recommend individualised exercise and education over passive treatment alone."],
  mnemonic:{word:"Nod = Nutation", items:[["Nutation","Sacral base nods forward in standing"],["Counter","Base moves back in sitting slumped or lying"],["Closure","Form (shape) plus force (muscles)"]], extra:"SIJ: synovial in front, fibrous behind."},
  example:"A 29-year-old woman in Mangaluru, 30 weeks pregnant, has sharp pain over the pubic bone and buttock on climbing stairs and turning in bed; she is taught a pelvic belt and log-roll technique.",
  flags:["Night pain and morning stiffness in a young adult (sacroiliitis, spondyloarthritis)","Fever with severe SIJ pain (septic sacroiliitis, especially after delivery or drug use)","Pelvic pain after trauma with inability to bear weight (fracture)"],
  viva:[["Type of pubic symphysis?","Secondary cartilaginous joint."],["Which ligament is the strongest at the SIJ?","Interosseous sacroiliac ligament."],["Define nutation.","Forward-downward movement of the sacral promontory relative to the ilia."]],
  refs:[{c:"Chaurasia BD. Human Anatomy, Volume 2: Lower Limb, Abdomen and Pelvis. Chapter: Joints of pelvis."},{b:"levangie",ch:"The vertebral column - sacroiliac joint"},{b:"magee",ch:"Pelvis"}],
  keywords:"sacroiliac joint pubic symphysis pelvic joints nutation pelvic girdle pain",
  mcq:[["Nutation of the sacrum is mainly resisted by:",["Long posterior sacroiliac ligament","Sacrotuberous and sacrospinous ligaments","Iliolumbar ligament only","Inguinal ligament"],1,"Nutation is resisted by sacrotuberous, sacrospinous and interosseous ligaments; counternutation by the long posterior ligament."],["The sacroiliac joint is best described as:",["Pure fibrous joint","Synovial joint anteriorly with a syndesmosis posteriorly","Secondary cartilaginous joint","Ball and socket joint"],1,"It is synovial in front and fibrous behind."]]
},
{
  id:"ah-abdominal-wall-inguinal-canal", title:"Abdominal wall layers, rectus sheath and inguinal canal", subject:"Anatomy", region:"Abdomen",
  stages:"steps",
  aliases:["anterior abdominal wall","rectus sheath","inguinal canal","external oblique","transversus abdominis","linea alba","inguinal hernia"],
  simple:"The front of the abdomen is built in layers: skin, fat, three flat muscles (external oblique, internal oblique, transversus abdominis) and the straight rectus abdominis inside its sheath. The flat muscles' tendons wrap the rectus to form the rectus sheath. Low down, the inguinal canal is a short tunnel through these layers, and it is a weak spot where hernias appear.",
  flow:["Layers: skin, Camper and Scarpa fascia, muscles, fascia, peritoneum","Flat muscles: external oblique, internal oblique, transversus abdominis","Rectus abdominis in rectus sheath; linea alba in midline","Supplied by T7-T12 and L1 (iliohypogastric, ilioinguinal)","Inguinal canal: 4 cm oblique passage above inguinal ligament","Hernia, diastasis recti and core training are applied points"],
  exam:[
    {h:"Layers of the anterior abdominal wall", p:["Skin; superficial fascia with fatty (Camper) and membranous (Scarpa) layers; external oblique, internal oblique, transversus abdominis (laterally) or rectus in its sheath (medially); transversalis fascia; extraperitoneal fat; parietal peritoneum.","Dermatomes: T7 at the xiphoid region, T10 at the umbilicus, L1 above the inguinal ligament."]},
    {h:"Muscles: attachments, nerve supply, actions", p:["External oblique: outer surfaces of lower 8 ribs; fibres down, forward and medially to iliac crest, aponeurosis to linea alba and pubic tubercle; its lower free border forms the inguinal ligament (ASIS to pubic tubercle).","Internal oblique: thoracolumbar fascia, anterior two-thirds of iliac crest, lateral two-thirds of inguinal ligament; to lower 3-4 ribs, aponeurosis to linea alba and, with transversus, the conjoint tendon to pubic crest and pectineal line.","Transversus abdominis: inner surfaces of lower 6 costal cartilages, thoracolumbar fascia, iliac crest, lateral one-third of inguinal ligament; fibres horizontal to linea alba and conjoint tendon.","Rectus abdominis: pubic crest and symphysis to 5th-7th costal cartilages and xiphoid; three tendinous intersections attach it to the anterior sheath. Pyramidalis tenses linea alba.","Nerve supply: lower 6 thoracic nerves (T7-T12) and L1 (iliohypogastric and ilioinguinal); actions: support viscera, raise intra-abdominal pressure (cough, defecation, labour, forced expiration), trunk flexion (rectus), rotation and side flexion (obliques, external oblique to the opposite side, internal oblique to the same side), transversus stiffens the lumbopelvic region."]},
    {h:"Rectus sheath", p:["Above the costal margin: anterior wall only (external oblique aponeurosis); rectus lies on costal cartilages.","Between costal margin and arcuate line: anterior wall by external oblique and anterior lamina of internal oblique aponeurosis; posterior wall by posterior lamina of internal oblique and transversus aponeurosis.","Below the arcuate line (about midway between umbilicus and pubis): all aponeuroses pass in front; posteriorly only transversalis fascia.","Contents: rectus, pyramidalis, superior and inferior epigastric vessels, terminal parts of lower 6 thoracic nerves."]},
    {h:"Inguinal canal", p:["Oblique passage about 4 cm long above the medial half of the inguinal ligament, from deep ring (in transversalis fascia, 1.25 cm above midinguinal point, lateral to inferior epigastric artery) to superficial ring (in external oblique aponeurosis above and lateral to the pubic tubercle).","Walls: anterior - external oblique aponeurosis plus internal oblique laterally; posterior - transversalis fascia plus conjoint tendon medially; roof - arching fibres of internal oblique and transversus; floor - grooved inguinal ligament with lacunar ligament medially.","Contents: spermatic cord in males (ductus deferens, testicular vessels, pampiniform plexus, genital branch of genitofemoral nerve) or round ligament of uterus in females, plus ilioinguinal nerve (which enters the canal through its wall, not the deep ring).","Mechanisms of protection: obliquity, muscles guarding the rings, shutter action of internal oblique arches, ball-valve action of cremaster."]},
    {h:"Applied anatomy and physiotherapy relevance", p:["Indirect inguinal hernia passes through the deep ring lateral to the inferior epigastric artery (common in young males); direct hernia bulges through Hesselbach triangle medial to the artery (older men, weak conjoint tendon).","Diastasis recti (widening of linea alba, common in pregnancy) is managed with transversus and pelvic floor activation, progressive abdominal loading and posture.","After abdominal surgery: splinted coughing, early mobilisation, breathing exercises, avoid heavy lifting for about 4-6 weeks as advised; lower abdominal reflexes test T10-T12.","Core training uses the abdominal cylinder (transversus, multifidus, diaphragm, pelvic floor) in low back pain; Beevor sign (umbilicus moves up on curl-up) indicates lower rectus weakness from a lesion near T10."]},
    {h:"Conclusion", p:["The layered abdominal wall, its rectus sheath and the inguinal canal explain hernias and form the anatomical basis of core and postoperative physiotherapy."]}
  ],
  tip:"Draw transverse sections of the rectus sheath above the costal margin, above the arcuate line and below it, plus a front view of the inguinal canal showing deep and superficial rings and inferior epigastric artery.",
  evidence:[["Exercise for postpartum diastasis recti","May reduce inter-rectus distance; quality of evidence low","Low"],["Motor control exercise for chronic low back pain","Similar benefit to other exercise forms","Moderate"],["Prehabilitation before abdominal surgery","May reduce postoperative pulmonary complications","Low-moderate"]],
  evidenceSource:"B D Chaurasia; Cochrane review of motor control exercise for chronic low back pain (Saragiotto et al. 2016); systematic reviews on diastasis recti exercise",
  outcomes:[["Inter-rectus distance (finger widths, calipers or ultrasound)","Diastasis recti severity"],["Pressure biofeedback (prone abdominal hollowing)","Transversus activation"],["Cough strength or peak cough flow","Abdominal muscle function after surgery"]],
  recent:["Ultrasound imaging is increasingly used by physiotherapists to measure inter-rectus distance and give biofeedback for transversus activation."],
  mnemonic:{word:"MALT (from the top, clockwise: roof, front, floor, back)", items:[["M","Roof: 2 Muscles (arching internal oblique and transversus)"],["A","Anterior wall: 2 Aponeuroses (external oblique, internal oblique laterally)"],["L","Floor: 2 Ligaments (inguinal, lacunar)"],["T","Posterior wall: 2 Ts (Transversalis fascia, conjoint Tendon)"]], extra:"Indirect hernia: lateral to inferior epigastric artery; direct: medial."},
  example:"A 32-year-old mother in Kanpur, 3 months after her second delivery, notices a ridge bulging in the middle of her abdomen when sitting up from lying: diastasis recti.",
  flags:["Painful, tense, irreducible groin lump with vomiting (strangulated hernia, emergency)","Wound discharge or fever after abdominal surgery","Abdominal pain with rigidity (peritonitis, refer)"],
  viva:[["What forms the inguinal ligament?","The folded lower free border of the external oblique aponeurosis."],["What is deficient below the arcuate line?","The posterior wall of the rectus sheath (aponeurotic part)."],["Nerve supply of abdominal muscles?","T7-T12 and L1 (iliohypogastric, ilioinguinal)."]],
  refs:[{c:"Chaurasia BD. Human Anatomy, Volume 2: Lower Limb, Abdomen and Pelvis. Chapter: Anterior abdominal wall."},{b:"kendall",ch:"Trunk muscles"},{b:"kisner",ch:"The spine: exercise interventions"}],
  keywords:"abdominal wall rectus sheath inguinal canal hernia external oblique transversus",
  mcq:[["The deep inguinal ring is an opening in the:",["External oblique aponeurosis","Internal oblique","Transversalis fascia","Conjoint tendon"],2,"The deep ring is in the transversalis fascia."],["A direct inguinal hernia passes:",["Through the deep ring","Lateral to the inferior epigastric artery","Through Hesselbach triangle medial to the inferior epigastric artery","Through the femoral canal"],2,"Direct hernias push through the weak posterior wall medial to the artery."]]
},
{
  id:"ah-abdominal-aorta-iliac", title:"Abdominal aorta and iliac arteries", subject:"Anatomy", region:"Abdomen",
  stages:"steps",
  aliases:["abdominal aorta","common iliac artery","internal iliac artery","external iliac artery","coeliac trunk","abdominal aortic aneurysm","aortic bifurcation"],
  simple:"The abdominal aorta is the main artery of the abdomen. It enters through the diaphragm at T12, gives branches to the gut, kidneys and body wall, and divides at L4 into two common iliac arteries. Each common iliac splits into the internal iliac for the pelvis and buttock and the external iliac, which becomes the femoral artery of the leg.",
  flow:["Enters abdomen at T12 through aortic opening","Unpaired ventral: coeliac (T12), SMA (L1), IMA (L3)","Paired lateral: suprarenal, renal, gonadal arteries","Bifurcates at L4 into common iliac arteries","Common iliac divides at L5-S1 into internal and external","Aneurysm, claudication and exercise safety are applied points"],
  exam:[
    {h:"Course and relations", p:["Begins at the aortic opening of the diaphragm at T12 as the continuation of the descending thoracic aorta; descends on the lumbar vertebral bodies slightly left of midline.","Ends at the lower border of L4 (about the level of the supracristal plane, slightly below and left of the umbilicus) by dividing into right and left common iliac arteries; median sacral artery continues downward.","Relations: in front - coeliac plexus, pancreas, left renal vein, third part of duodenum, root of mesentery; behind - lumbar vertebrae and left lumbar veins; right - IVC and cisterna chyli; left - left sympathetic trunk."]},
    {h:"Branches", p:["Ventral unpaired (gut): coeliac trunk (T12; foregut - left gastric, splenic, common hepatic), superior mesenteric (L1; midgut), inferior mesenteric (L3; hindgut).","Lateral paired (organs): middle suprarenal (L1), renal (L1-L2; right passes behind IVC), gonadal - testicular or ovarian (L2).","Dorsolateral paired (wall): inferior phrenic (T12), four pairs of lumbar arteries (L1-L4).","Terminal: two common iliac arteries and the single median sacral artery."]},
    {h:"Common and external iliac arteries", p:["Common iliac: from L4 bifurcation to the front of the sacroiliac joint (L5-S1 level), where it divides into external and internal iliac arteries; no named branches.","External iliac: runs along the pelvic brim on psoas major; gives inferior epigastric and deep circumflex iliac arteries; passes under the inguinal ligament at the midinguinal point (midway between ASIS and pubic symphysis) to become the femoral artery."]},
    {h:"Internal iliac artery", p:["About 4 cm long; descends into the pelvis at the sacroiliac joint and divides at the upper margin of the greater sciatic notch into anterior and posterior divisions.","Posterior division (to wall and buttock): iliolumbar, lateral sacral, superior gluteal (largest branch, leaves above piriformis).","Anterior division (viscera, perineum, buttock and thigh): superior vesical (with umbilical artery remnant), obturator, inferior vesical (male) or vaginal and uterine (female), middle rectal, internal pudendal, inferior gluteal."]},
    {h:"Collateral circulation", p:["Aortic or iliac block is bypassed through internal thoracic - superior epigastric - inferior epigastric anastomoses, lumbar and iliolumbar anastomoses, and the cruciate and trochanteric anastomoses around the hip.","Slowly developing narrowing allows collaterals to open, which is the basis of exercise training in peripheral arterial disease."]},
    {h:"Applied anatomy and physiotherapy relevance", p:["Abdominal aortic aneurysm (usually below the renal arteries) may present as a pulsatile mass, back or abdominal pain; rupture is fatal, so a pulsatile mass with back pain needs urgent referral, never deep abdominal massage.","Aortoiliac occlusion (Leriche syndrome): buttock and thigh claudication, weak femoral pulses and erectile dysfunction.","Peripheral arterial disease: supervised walking to moderate-to-near-maximal claudication pain, rest, repeat, for 30-60 minutes, 3 times a week for at least 12 weeks improves walking distance.","Check femoral, popliteal, dorsalis pedis and posterior tibial pulses and ankle-brachial index (below 0.9 is abnormal) before compression or heat to the legs; femoral pulse is felt at the midinguinal point."]},
    {h:"Conclusion", p:["The aorta and iliac arteries supply the abdomen, pelvis and lower limbs, and their disease underlies claudication and dangerous aneurysms that physiotherapists must recognise."]}
  ],
  tip:"Draw the abdominal aorta from the front with vertebral levels marked (T12, L1, L2, L3, L4), its three ventral, paired lateral branches and the iliac tree, with internal iliac divisions listed beside it.",
  evidence:[["Supervised exercise for intermittent claudication","Improves maximal walking distance more than usual care","High"],["Home-based structured walking for PAD","Improves walking distance, less than supervised","Moderate"],["Ultrasound screening for AAA in older men","Reduces aneurysm-related deaths","High"]],
  evidenceSource:"Cochrane review of exercise for intermittent claudication (Lane et al. 2017); AHA/ACC 2016 guideline on lower extremity PAD; MASS trial of AAA screening",
  outcomes:[["Ankle-brachial index","Severity of arterial disease"],["Six-minute walk or treadmill claudication distance","Walking capacity"],["Peripheral pulse examination","Arterial patency"]],
  recent:["The 2024 ACC/AHA multisociety guideline on lower extremity PAD continues to recommend structured exercise therapy as first-line care for claudication."],
  mnemonic:{word:"Coeliac 12, SMA 1, IMA 3, Split at 4", items:[["T12","Coeliac trunk"],["L1","Superior mesenteric artery"],["L3","Inferior mesenteric artery"],["L4","Bifurcation into common iliacs"]], extra:"Internal iliac posterior division: I Love Sex - Iliolumbar, Lateral sacral, Superior gluteal."},
  example:"A 68-year-old smoker from Ludhiana gets cramping pain in both buttocks and thighs after walking 150 m, relieved by rest, with weak femoral pulses: aortoiliac occlusive disease.",
  flags:["Pulsatile abdominal mass with sudden back or abdominal pain (ruptured AAA, emergency)","Cold, pale, pulseless, painful leg (acute limb ischaemia)","Rest pain or non-healing foot ulcer (critical limb ischaemia)"],
  viva:[["At what level does the aorta bifurcate?","Lower border of L4."],["Largest branch of internal iliac?","Superior gluteal artery (posterior division)."],["Where does the external iliac become the femoral artery?","Behind the inguinal ligament at the midinguinal point."]],
  refs:[{c:"Chaurasia BD. Human Anatomy, Volume 2: Lower Limb, Abdomen and Pelvis. Chapters: Abdominal aorta; Vessels of the pelvis."},{b:"acsm",ch:"Peripheral artery disease"},{b:"irwin",ch:"Vascular disease"}],
  keywords:"abdominal aorta branches iliac arteries internal iliac claudication aneurysm",
  mcq:[["The inferior mesenteric artery arises at the level of:",["T12","L1","L3","L5"],2,"The IMA arises at L3, behind the third part of the duodenum region."],["Which is a branch of the posterior division of the internal iliac artery?",["Obturator","Inferior gluteal","Superior gluteal","Internal pudendal"],2,"Posterior division: iliolumbar, lateral sacral, superior gluteal."]]
},
{
  id:"ah-urinary-tract-bladder-innervation", title:"Kidney, ureter, bladder and urethra; nerve supply of bladder", subject:"Anatomy", region:"Pelvis",
  stages:"steps",
  aliases:["kidney anatomy","ureter constrictions","urinary bladder","bladder innervation","micturition reflex","neurogenic bladder","urethra"],
  simple:"The kidneys filter blood and make urine, which flows down the ureters to the bladder and out through the urethra. The bladder is controlled by three sets of nerves: parasympathetic (S2-S4) to empty it, sympathetic (T11-L2) to help store urine, and the pudendal nerve (S2-S4) for the voluntary sphincter. Spinal cord injury disturbs this control, which matters greatly in rehabilitation.",
  flow:["Kidneys T12-L3, retroperitoneal; right slightly lower","Ureter 25 cm with three constrictions","Bladder: detrusor, trigone, internal and external sphincters","Parasympathetic S2-S4 pelvic splanchnics contract detrusor","Sympathetic T11-L2 relaxes detrusor; pudendal S2-S4 holds sphincter","Pontine centre coordinates; cord lesions cause neurogenic bladder"],
  exam:[
    {h:"Kidney", p:["Paired bean-shaped retroperitoneal organs on the posterior abdominal wall from T12 to L3; right kidney lies slightly lower because of the liver; hilum at L1 (transpyloric plane) with renal vein in front, artery, then pelvis behind.","Coverings from inside out: fibrous capsule, perirenal fat, renal fascia (Gerota), pararenal fat.","Internal structure: cortex, medulla with renal pyramids, minor and major calyces, renal pelvis; nephron is the functional unit; posterior relations include diaphragm, 12th rib, psoas, quadratus lumborum and transversus abdominis with subcostal, iliohypogastric and ilioinguinal nerves."]},
    {h:"Ureter", p:["About 25 cm long muscular tube from renal pelvis to bladder, half abdominal and half pelvic; runs on psoas, crosses the bifurcation of the common iliac artery at the pelvic brim, enters the bladder obliquely (acting as a valve).","Three constrictions where stones lodge: pelviureteric junction, pelvic brim, and its passage through the bladder wall (ureterovesical junction, narrowest).","Ureteric colic is referred along T11-L2 dermatomes: loin to groin, scrotum or labia and front of thigh."]},
    {h:"Urinary bladder and urethra", p:["Bladder: muscular reservoir behind the pubic symphysis; empty bladder is pyramidal with apex, base, neck and superior and inferolateral surfaces; capacity about 400-600 ml in adults; desire to void felt at about 150-250 ml.","Detrusor muscle in the wall; trigone (smooth area between the two ureteric openings and internal urethral orifice); internal sphincter (smooth, at the neck, especially in males) and external urethral sphincter (striated, voluntary) in the urogenital region.","Urethra: female about 4 cm (short, explaining frequent infection and stress incontinence); male about 18-20 cm with prostatic, membranous (narrowest, surrounded by external sphincter) and spongy parts."]},
    {h:"Nerve supply of the bladder", p:["Parasympathetic: pelvic splanchnic nerves (nervi erigentes, S2-S4); motor to detrusor, inhibitory to internal sphincter; causes emptying. Also carries stretch (fullness) and pain afferents.","Sympathetic: T11-L2 via superior hypogastric and inferior hypogastric (pelvic) plexuses; relaxes detrusor and contracts bladder neck, aiding storage and preventing retrograde ejaculation.","Somatic: pudendal nerve (S2-S4) supplies the external urethral sphincter and pelvic floor; voluntary control.","Central control: sacral micturition centre (S2-S4, conus medullaris at L1 vertebral level), pontine micturition centre coordinating detrusor contraction with sphincter relaxation, and frontal cortex for voluntary inhibition."]},
    {h:"Micturition and neurogenic bladder", p:["Filling: sympathetic and pudendal activity store urine; voiding: pontine centre triggers parasympathetic detrusor contraction with sphincter relaxation.","Lesion above the sacral centre (cervical or thoracic cord injury after spinal shock): reflex (spastic, upper motor neuron) bladder with small capacity, detrusor overactivity and often detrusor-sphincter dyssynergia.","Lesion of the sacral centre, conus, cauda equina or pelvic nerves: autonomous (flaccid, lower motor neuron) bladder with retention and overflow incontinence.","Lesion of cortex (stroke, dementia): uninhibited bladder with urgency and urge incontinence."]},
    {h:"Applied anatomy and physiotherapy relevance", p:["Spinal cord injury: clean intermittent catheterisation every 4-6 hours, fluid schedule, prevention of infection and autonomic dysreflexia (often from a full bladder in lesions at or above T6).","Stress urinary incontinence after childbirth or prostatectomy: pelvic floor muscle training, for example 8-12 maximal contractions held 6-10 seconds, three times a day for at least 3 months, with biofeedback when needed.","Urge incontinence: bladder training (timed voiding with gradual increase in interval), urge suppression and pelvic floor contraction; tibial nerve stimulation is an option with moderate evidence.","Cauda equina syndrome with retention or saddle anaesthesia is a surgical emergency; renal angle tenderness with fever suggests pyelonephritis, not mechanical back pain."]},
    {h:"Conclusion", p:["Understanding the urinary tract and its triple nerve supply explains bladder problems after neurological injury and guides catheter, pelvic floor and bladder training programmes."]}
  ],
  tip:"Draw the bladder with detrusor, trigone and sphincters, and a nerve diagram showing pontine centre, sympathetic T11-L2 via hypogastric plexus, parasympathetic S2-S4 pelvic splanchnics and pudendal S2-S4 to the external sphincter.",
  evidence:[["Pelvic floor muscle training for stress urinary incontinence in women","Cures or improves symptoms more than no treatment","High"],["Bladder training for urge incontinence","May help; evidence low certainty","Low"],["Percutaneous tibial nerve stimulation for overactive bladder","Improves symptoms versus sham","Moderate"]],
  evidenceSource:"Cochrane review of pelvic floor muscle training for urinary incontinence in women (Dumoulin et al. 2018); NICE guideline NG123 on urinary incontinence in women (2019)",
  outcomes:[["Bladder diary","Frequency, volumes and leakage episodes"],["Modified Oxford scale","Pelvic floor muscle strength"],["ICIQ-UI Short Form","Severity and impact of incontinence"]],
  recent:["NICE guideline NG123 (2019) recommends supervised pelvic floor muscle training of at least 3 months as first-line treatment for stress incontinence in women."],
  mnemonic:{word:"S2, 3, 4 keeps the pee off the floor", items:[["Para (S2-S4)","Pee: detrusor contracts, bladder empties"],["Sympathetic (T11-L2)","Storage: detrusor relaxes, neck closes"],["Pudendal (S2-S4)","Personal control of external sphincter"]], extra:"Parasympathetic to Pee, Sympathetic to Store."},
  example:"A 25-year-old construction worker in Surat with a T8 complete spinal cord injury leaks urine suddenly with leg spasms 3 months after injury; urodynamics show detrusor overactivity with sphincter dyssynergia, and he is taught intermittent catheterisation.",
  flags:["Painless urinary retention or new incontinence with back pain or saddle numbness (cauda equina)","Pounding headache and high BP in SCI above T6 (autonomic dysreflexia, check bladder)","Fever with loin pain or blood in urine (pyelonephritis or stone)"],
  viva:[["Nerve that contracts the detrusor?","Pelvic splanchnic nerves (parasympathetic S2-S4)."],["Narrowest part of the ureter?","Ureterovesical junction (intramural part)."],["Bladder type in a cauda equina lesion?","Autonomous (flaccid, lower motor neuron) bladder with retention and overflow."]],
  refs:[{c:"Chaurasia BD. Human Anatomy, Volume 2: Lower Limb, Abdomen and Pelvis. Chapters: Kidney and ureter; Urinary bladder and urethra."},{b:"guyton",ch:"Micturition"},{b:"osullivan",ch:"Traumatic spinal cord injury"}],
  keywords:"kidney ureter bladder urethra bladder innervation neurogenic bladder micturition",
  mcq:[["The external urethral sphincter is supplied by the:",["Pelvic splanchnic nerves","Hypogastric nerves","Pudendal nerve","Obturator nerve"],2,"The striated external sphincter is supplied by the pudendal nerve (S2-S4)."],["A spinal cord injury at T6 (after spinal shock) typically produces a:",["Flaccid autonomous bladder","Reflex (spastic) bladder","Normal bladder","Uninhibited cortical bladder only"],1,"Lesions above the sacral centre give an upper motor neuron reflex bladder."]]
},
]);
